{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Gandi Domain Registrar Skill Configuration",
  "description": "Configuration for the Gandi domain registrar integration",
  "type": "object",
  "properties": {
    "apiToken": {
      "type": "string",
      "title": "API Token",
      "description": "Gandi Personal Access Token (PAT) for single-organization use. Supports environment variable references like ${GANDI_API_TOKEN}",
      "sensitive": true,
      "format": "password",
      "minLength": 10,
      "examples": ["${GANDI_API_TOKEN}", "your-personal-access-token-here"]
    },
    "apiUrl": {
      "type": "string",
      "title": "API URL",
      "description": "Gandi API base URL (optional, defaults to production). Use https://api.sandbox.gandi.net for testing",
      "format": "uri",
      "default": "https://api.gandi.net",
      "examples": ["https://api.gandi.net", "https://api.sandbox.gandi.net"]
    },
    "organizations": {
      "type": "array",
      "title": "Organizations",
      "description": "Multi-organization support. Define multiple Gandi organizations with separate tokens. If present, overrides single apiToken",
      "items": {
        "type": "object",
        "required": ["name", "apiToken", "sharingId"],
        "properties": {
          "name": {
            "type": "string",
            "title": "Name",
            "description": "Internal identifier for this organization (e.g., 'personal', 'work')",
            "pattern": "^[a-z0-9_-]+$",
            "minLength": 1,
            "examples": ["personal", "work", "client1"]
          },
          "label": {
            "type": "string",
            "title": "Label",
            "description": "Human-readable label for this organization",
            "minLength": 1,
            "examples": ["Personal Domains", "Work Organization", "Client - Acme Corp"]
          },
          "apiToken": {
            "type": "string",
            "title": "API Token",
            "description": "Gandi Personal Access Token for this organization. Supports environment variables",
            "sensitive": true,
            "format": "password",
            "minLength": 10,
            "examples": ["${GANDI_TOKEN_PERSONAL}", "${GANDI_TOKEN_WORK}"]
          },
          "sharingId": {
            "type": "string",
            "title": "Organization ID",
            "description": "Gandi organization UUID (sharing_id). Found in API response from /v5/organization/organizations",
            "format": "uuid",
            "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
            "examples": ["17672a84-e05e-11e7-b536-00163e6dc886"]
          },
          "default": {
            "type": "boolean",
            "title": "Default",
            "description": "Use this organization as the default when none is specified",
            "default": false
          }
        }
      }
    },
    "domainChecker": {
      "type": "object",
      "title": "Domain Availability Checker",
      "description": "Configuration for domain availability checking and suggestions",
      "properties": {
        "tlds": {
          "type": "object",
          "title": "TLD Configuration",
          "properties": {
            "mode": {
              "type": "string",
              "title": "TLD Mode",
              "description": "How to handle TLD lists",
              "enum": ["extend", "replace"],
              "default": "extend",
              "enumDescriptions": [
                "Merge custom TLDs with defaults",
                "Use only custom TLDs (ignore defaults)"
              ]
            },
            "defaults": {
              "type": "array",
              "title": "Default TLDs",
              "description": "Default TLD list (used when mode is 'extend' or when custom is empty)",
              "items": {
                "type": "string",
                "pattern": "^[a-z0-9-]+$"
              },
              "default": ["com", "net", "org", "info", "io", "dev", "app", "ai", "tech", "co", "biz", "me", "us"],
              "examples": [["com", "net", "org", "io", "dev", "app"]]
            },
            "custom": {
              "type": "array",
              "title": "Custom TLDs",
              "description": "Custom TLD list to add or replace defaults",
              "items": {
                "type": "string",
                "pattern": "^[a-z0-9-]+$"
              },
              "default": [],
              "examples": [["co.uk", "co.ua", "eu", "de"]]
            }
          }
        },
        "variations": {
          "type": "object",
          "title": "Name Variations",
          "description": "Domain name variation generation settings",
          "properties": {
            "enabled": {
              "type": "boolean",
              "title": "Enabled",
              "description": "Enable domain name variation generation",
              "default": true
            },
            "patterns": {
              "type": "array",
              "title": "Variation Patterns",
              "description": "Which types of variations to generate",
              "items": {
                "type": "string",
                "enum": ["hyphenated", "abbreviated", "prefix", "suffix", "numbers"]
              },
              "default": ["hyphenated", "abbreviated", "prefix", "suffix", "numbers"],
              "uniqueItems": true
            },
            "prefixes": {
              "type": "array",
              "title": "Prefixes",
              "description": "Word prefixes for prefix variations",
              "items": {
                "type": "string"
              },
              "default": ["get", "my", "the", "try"],
              "examples": [["get", "my", "the", "try", "use"]]
            },
            "suffixes": {
              "type": "array",
              "title": "Suffixes",
              "description": "Word suffixes for suffix variations",
              "items": {
                "type": "string"
              },
              "default": ["app", "hub", "io", "ly", "ai", "hq"],
              "examples": [["app", "hub", "io", "ly", "ai", "hq", "dev"]]
            },
            "maxNumbers": {
              "type": "integer",
              "title": "Max Numbers",
              "description": "Maximum number suffix to generate (e.g., 3 = domain2, domain3, domain4)",
              "minimum": 1,
              "maximum": 10,
              "default": 3
            }
          }
        },
        "rateLimit": {
          "type": "object",
          "title": "Rate Limiting",
          "description": "API rate limiting configuration for good citizenship",
          "properties": {
            "maxConcurrent": {
              "type": "integer",
              "title": "Max Concurrent Requests",
              "description": "Maximum number of concurrent API requests",
              "minimum": 1,
              "maximum": 10,
              "default": 3
            },
            "delayMs": {
              "type": "integer",
              "title": "Delay Between Requests (ms)",
              "description": "Minimum delay between requests in milliseconds",
              "minimum": 0,
              "maximum": 5000,
              "default": 200
            },
            "maxRequestsPerMinute": {
              "type": "integer",
              "title": "Max Requests Per Minute",
              "description": "Maximum requests per minute (Gandi allows 1000, we use 10%)",
              "minimum": 1,
              "maximum": 1000,
              "default": 100
            }
          }
        },
        "limits": {
          "type": "object",
          "title": "Result Limits",
          "description": "Limits on result counts to prevent excessive API usage",
          "properties": {
            "maxTlds": {
              "type": "integer",
              "title": "Max TLDs to Check",
              "description": "Maximum number of TLDs to check in suggestions",
              "minimum": 1,
              "maximum": 20,
              "default": 5
            },
            "maxVariations": {
              "type": "integer",
              "title": "Max Name Variations",
              "description": "Maximum number of name variations to generate",
              "minimum": 1,
              "maximum": 50,
              "default": 10
            }
          }
        }
      }
    }
  },
  "examples": [
    {
      "apiToken": "${GANDI_API_TOKEN}"
    },
    {
      "apiToken": "${GANDI_API_TOKEN}",
      "domainChecker": {
        "tlds": {
          "mode": "extend",
          "custom": ["co.uk", "eu"]
        },
        "limits": {
          "maxTlds": 5,
          "maxVariations": 10
        }
      }
    },
    {
      "organizations": [
        {
          "name": "personal",
          "label": "Personal Domains",
          "apiToken": "${GANDI_TOKEN_PERSONAL}",
          "sharingId": "17672a84-e05e-11e7-b536-00163e6dc886",
          "default": true
        },
        {
          "name": "work",
          "label": "Work Organization",
          "apiToken": "${GANDI_TOKEN_WORK}",
          "sharingId": "a1b2c3d4-e5f6-7890-abcd-ef1234567890"
        }
      ]
    }
  ]
}

#!/usr/bin/env node

/**
 * Add or update a DNS record
 * Usage: node add-dns-record.js <domain> <name> <type> <value> [ttl]
 * Examples:
 *   node add-dns-record.js example.com @ A 192.168.1.1
 *   node add-dns-record.js example.com www CNAME @ 300
 *   node add-dns-record.js example.com @ MX "10 mail.example.com." 10800
 */

import { 
  createDnsRecord, 
  validateRecordValue, 
  getDnsRecord,
  sanitizeDomain,
  sanitizeRecordName,
  sanitizeTTL
} from './gandi-api.js';

const [,, rawDomain, rawName, type, ...rest] = process.argv;

// Check required arguments
if (!rawDomain || !rawName || !type || rest.length === 0) {
  console.error('❌ Usage: node add-dns-record.js <domain> <name> <type> <value> [ttl]');
  console.error('');
  console.error('Examples:');
  console.error('  node add-dns-record.js example.com @ A 192.168.1.1');
  console.error('  node add-dns-record.js example.com www CNAME @ 300');
  console.error('  node add-dns-record.js example.com @ MX "10 mail.example.com." 10800');
  console.error('  node add-dns-record.js example.com @ TXT "v=spf1 include:_spf.google.com ~all"');
  console.error('');
  console.error('Record types: A, AAAA, CNAME, MX, TXT, NS, SRV, CAA, PTR');
  console.error('Name: Use @ for root domain, or subdomain name');
  console.error('TTL: Time to live in seconds (300-2592000, default: 10800)');
  process.exit(1);
}

// Sanitize inputs for security
let domain, name, ttl;
try {
  domain = sanitizeDomain(rawDomain);
  name = sanitizeRecordName(rawName);
} catch (error) {
  console.error(`❌ Invalid input: ${error.message}`);
  process.exit(1);
}

// Parse TTL (last argument might be TTL)
let value;
ttl = 10800; // Default 3 hours

if (rest.length > 1) {
  // Check if last arg is a number (TTL)
  const lastArg = rest[rest.length - 1];
  if (!isNaN(parseInt(lastArg))) {
    try {
      ttl = sanitizeTTL(parseInt(lastArg));
      value = rest.slice(0, -1).join(' ');
    } catch (error) {
      console.error(`❌ Invalid TTL: ${error.message}`);
      process.exit(1);
    }
  } else {
    value = rest.join(' ');
  }
} else {
  value = rest[0];
}

async function main() {
  try {
    console.log(`🔄 Adding/updating ${type} record for ${name}.${domain}...`);
    console.log(`   Value: ${value}`);
    console.log(`   TTL: ${ttl}s`);
    console.log('');

    // Validate record value
    const validation = validateRecordValue(type, value);
    if (!validation.valid) {
      console.error(`❌ Validation error: ${validation.error}`);
      process.exit(1);
    }

    // Check if record already exists
    let existingRecord = null;
    try {
      existingRecord = await getDnsRecord(domain, name, type);
      console.log('ℹ️  Record already exists, will be replaced:');
      console.log(`   Current value(s): ${existingRecord.rrset_values.join(', ')}`);
      console.log(`   Current TTL: ${existingRecord.rrset_ttl}s`);
      console.log('');
    } catch (error) {
      // Record doesn't exist, that's okay
      console.log('ℹ️  Creating new record...');
      console.log('');
    }

    // Create/update the record
    const result = await createDnsRecord(domain, name, type, [value], ttl);

    if (result.statusCode === 201) {
      console.log('✅ DNS record created successfully!');
    } else if (result.statusCode === 200) {
      console.log('✅ DNS record updated successfully!');
    } else {
      console.log(`✅ DNS record saved (status: ${result.statusCode})`);
    }

    console.log('');
    console.log('📋 Record details:');
    console.log(`   Domain: ${domain}`);
    console.log(`   Name: ${name}`);
    console.log(`   Type: ${type}`);
    console.log(`   Value: ${value}`);
    console.log(`   TTL: ${ttl}s (${Math.floor(ttl / 60)} minutes)`);
    console.log('');
    console.log('⏱️  DNS propagation may take a few minutes.');
    console.log('   Verify with: dig @ns1.gandi.net ' + (name === '@' ? domain : `${name}.${domain}`) + ' ' + type);

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('   Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('   Permission denied. Ensure your token has LiveDNS write access.');
    } else if (error.statusCode === 404) {
      console.error(`   Domain ${domain} not found or not using Gandi LiveDNS.`);
    } else if (error.response) {
      console.error('   API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Create an email forward
 * Usage: node add-email-forward.js <domain> <mailbox> <destination> [destination2] [destination3]...
 * Examples:
 *   node add-email-forward.js example.com hello you@example.com
 *   node add-email-forward.js example.com contact support@example.com sales@example.com
 *   node add-email-forward.js example.com @ catchall@example.com  # Catch-all
 */

import { createEmailForward, getEmailForward, sanitizeDomain, sanitizeRecordName } from './gandi-api.js';

const [,, rawDomain, rawMailbox, ...destinations] = process.argv;

if (!rawDomain || !rawMailbox || destinations.length === 0) {
  console.error('❌ Usage: node add-email-forward.js <domain> <mailbox> <destination> [destination2]...');
  console.error('');
  console.error('Examples:');
  console.error('  node add-email-forward.js example.com hello you@example.com');
  console.error('  node add-email-forward.js example.com contact support@example.com sales@example.com');
  console.error('  node add-email-forward.js example.com @ catchall@example.com  # Catch-all');
  console.error('');
  console.error('Mailbox:');
  console.error('  - Use @ for catch-all (forwards all unmatched emails)');
  console.error('  - Use specific name (hello, contact, support, etc.)');
  console.error('');
  console.error('Destinations:');
  console.error('  - One or more email addresses to forward to');
  console.error('  - Multiple destinations = email sent to all');
  process.exit(1);
}

// Sanitize inputs for security
let domain, mailbox;
try {
  domain = sanitizeDomain(rawDomain);
  mailbox = sanitizeRecordName(rawMailbox); // Mailbox names follow same rules as DNS records
} catch (error) {
  console.error(`❌ Invalid input: ${error.message}`);
  process.exit(1);
}

// Validate email addresses
function isValidEmail(email) {
  return email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
}

async function main() {
  try {
    // Validate destination emails
    const invalidEmails = destinations.filter(email => !isValidEmail(email));
    if (invalidEmails.length > 0) {
      console.error('❌ Invalid email address(es):');
      invalidEmails.forEach(email => console.error(`   - ${email}`));
      process.exit(1);
    }

    const sourceDisplay = mailbox === '@' ? '@ (catch-all)' : mailbox;
    console.log(`📧 Creating email forward for ${sourceDisplay}@${domain}...`);
    console.log(`   Forwarding to: ${destinations.join(', ')}`);
    console.log('');

    // Check if forward already exists
    try {
      const existing = await getEmailForward(domain, mailbox);
      console.error('❌ Email forward already exists!');
      console.error(`   Current destinations: ${existing.destinations.join(', ')}`);
      console.error('');
      console.error('💡 To update this forward:');
      console.error(`   node update-email-forward.js ${domain} ${mailbox} ${destinations.join(' ')}`);
      console.error('');
      console.error('💡 To delete and recreate:');
      console.error(`   node delete-email-forward.js ${domain} ${mailbox}`);
      process.exit(1);
    } catch (error) {
      if (error.statusCode !== 404) {
        throw error;
      }
      // Forward doesn't exist, proceed with creation
    }

    // Create the forward
    const result = await createEmailForward(domain, mailbox, destinations);

    console.log('✅ Email forward created successfully!');
    console.log('');
    console.log('📋 Forward details:');
    console.log(`   From: ${sourceDisplay}@${domain}`);
    console.log(`   To:`);
    destinations.forEach(dest => {
      console.log(`   → ${dest}`);
    });
    console.log('');
    console.log('⏱️  Email forwarding should be active immediately.');
    console.log('   Test by sending an email to ' + (mailbox === '@' ? 'any address' : mailbox) + '@' + domain);
    console.log('');
    console.log('💡 To list all forwards:');
    console.log(`   node list-email-forwards.js ${domain}`);

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('   Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('   Permission denied. Ensure your token has Email write access.');
    } else if (error.statusCode === 404) {
      console.error(`   Domain ${domain} not found or email service not enabled.`);
      console.error('   Enable Gandi Mail service in your domain settings.');
    } else if (error.statusCode === 409) {
      console.error('   Email forward already exists. Use update-email-forward.js instead.');
    } else if (error.response) {
      console.error('   API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * View detailed SSL certificate information
 * 
 * Usage:
 *   node cert-details.js <certificate-id>
 * 
 * Examples:
 *   node cert-details.js abc123-uuid
 */

import { getCertificate } from './gandi-api.js';

// Parse command line arguments
const args = process.argv.slice(2);

if (args.length < 1) {
  console.error('Usage: node cert-details.js <certificate-id>');
  console.error('');
  console.error('Examples:');
  console.error('  node cert-details.js abc123-uuid');
  console.error('');
  console.error('💡 To list all certificates:');
  console.error('   node list-certificates.js');
  process.exit(1);
}

const certId = args[0];

// Format date nicely
function formatDate(dateString) {
  if (!dateString) return 'N/A';
  const date = new Date(dateString);
  return date.toLocaleString('en-US', { 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

// Main function
async function main() {
  try {
    console.log(`🔒 Fetching certificate details...`);
    console.log('');

    const cert = await getCertificate(certId);

    console.log('📋 Certificate Details:');
    console.log('');
    console.log('═'.repeat(70));

    // Basic info
    console.log(`Common Name: ${cert.cn || 'N/A'}`);

    if (cert.id || cert.uuid) {
      console.log(`ID: ${cert.id || cert.uuid}`);
    }

    if (cert.status) {
      const statusEmoji = {
        'valid': '✅',
        'pending': '⏳',
        'expired': '❌',
        'revoked': '🚫'
      };
      console.log(`Status: ${statusEmoji[cert.status] || '❓'} ${cert.status.toUpperCase()}`);
    }

    console.log('');

    // Subject Alternative Names
    if (cert.alt_names && cert.alt_names.length > 0) {
      console.log('Subject Alternative Names (SANs):');
      cert.alt_names.forEach(san => {
        console.log(`  • ${san}`);
      });
      console.log('');
    }

    // Dates
    if (cert.dates) {
      console.log('Dates:');
      if (cert.dates.created_at) {
        console.log(`  Created: ${formatDate(cert.dates.created_at)}`);
      }
      if (cert.dates.valid_from) {
        console.log(`  Valid From: ${formatDate(cert.dates.valid_from)}`);
      }
      if (cert.dates.valid_to) {
        console.log(`  Valid Until: ${formatDate(cert.dates.valid_to)}`);

        // Calculate expiry
        const validTo = new Date(cert.dates.valid_to);
        const now = new Date();
        const daysUntilExpiry = Math.ceil((validTo - now) / (1000 * 60 * 60 * 24));

        if (daysUntilExpiry < 0) {
          console.log(`  ❌ EXPIRED ${Math.abs(daysUntilExpiry)} days ago`);
        } else if (daysUntilExpiry < 30) {
          console.log(`  ⚠️  Expires in ${daysUntilExpiry} days`);
        } else {
          console.log(`  ✅ ${daysUntilExpiry} days remaining`);
        }
      }
      console.log('');
    }

    // Certificate details
    if (cert.package) {
      console.log(`Certificate Type: ${cert.package}`);
    }

    if (cert.dcv_method) {
      console.log(`Validation Method: ${cert.dcv_method.toUpperCase()}`);
    }

    if (cert.auto_renew !== undefined) {
      console.log(`Auto-renewal: ${cert.auto_renew ? '✅ Enabled' : '❌ Disabled'}`);
    }

    if (cert.key_size) {
      console.log(`Key Size: ${cert.key_size} bits`);
    }

    if (cert.signature_algorithm) {
      console.log(`Signature Algorithm: ${cert.signature_algorithm}`);
    }

    console.log('');

    // Additional info
    if (cert.csr) {
      console.log('CSR: Present');
    }

    if (cert.crt) {
      console.log('Certificate: Issued');
    }

    if (cert.chain) {
      console.log('Certificate Chain: Present');
    }

    console.log('');
    console.log('═'.repeat(70));

    // Actions
    console.log('');
    console.log('💡 Actions:');

    if (cert.status === 'valid') {
      console.log('   • Certificate is valid and active');
    } else if (cert.status === 'pending') {
      console.log('   • Certificate is pending validation');
      console.log('   • Complete domain validation to issue certificate');
    } else if (cert.status === 'expired') {
      console.log('   ⚠️  Certificate has expired!');
      console.log('   • Request a new certificate: node request-certificate.js');
    }

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('');
      console.error('Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('');
      console.error('Permission denied. Check token scopes.');
    } else if (error.statusCode === 404) {
      console.error('');
      console.error('Certificate not found. Check the certificate ID.');
      console.error('');
      console.error('💡 To list all certificates:');
      console.error('   node list-certificates.js');
    } else if (error.response) {
      console.error('API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Check Domain Availability
 * Single domain lookup with pricing and details
 * 
 * Usage:
 *   node check-domain.js example.com
 *   node check-domain.js example  (will add .com if no TLD)
 */

import { checkAvailability, sanitizeDomain } from './gandi-api.js';

const rawDomain = process.argv[2];

if (!rawDomain) {
  console.error('Usage: node check-domain.js <domain>');
  console.error('Example: node check-domain.js example.com');
  process.exit(1);
}

// Add .com if no TLD provided
const domainWithTld = rawDomain.includes('.') ? rawDomain : `${rawDomain}.com`;

// Sanitize domain input for security
let domainToCheck;
try {
  domainToCheck = sanitizeDomain(domainWithTld);
} catch (error) {
  console.error(`❌ Invalid domain: ${error.message}`);
  process.exit(1);
}

console.log(`🔍 Checking availability for: ${domainToCheck}\n`);

try {
  const results = await checkAvailability([domainToCheck]);

  if (!results || !results.products || results.products.length === 0) {
    console.log('❌ No results returned from API');
    process.exit(1);
  }

  const product = results.products[0];
  const currency = results.currency || 'USD';

  // Display results
  console.log('Domain:', product.name);
  console.log('');

  if (product.status === 'available') {
    console.log('✅ Status: AVAILABLE');

    // Show pricing
    if (product.prices && product.prices.length > 0) {
      console.log('\n💰 Pricing:');
      product.prices.forEach(price => {
        const durationUnit = price.duration_unit === 'y' ? 'year' : price.duration_unit;
        const minDuration = price.min_duration || 1;
        const maxDuration = price.max_duration;
        const durationLabel = maxDuration && maxDuration !== minDuration 
          ? `${minDuration}-${maxDuration} ${durationUnit}s`
          : `${minDuration} ${durationUnit}${minDuration > 1 ? 's' : ''}`;

        const priceAmount = price.price_after_taxes.toFixed(2);

        // Show discount if available
        if (price.discount && price.normal_price_after_taxes) {
          const normalPrice = price.normal_price_after_taxes.toFixed(2);
          console.log(`  ${durationLabel}: $${priceAmount} ${currency} (normally $${normalPrice})`);
        } else {
          console.log(`  ${durationLabel}: $${priceAmount} ${currency}`);
        }
      });
    }

    // Show supported features
    if (product.process) {
      console.log('\n📋 Supported Features:');
      if (Array.isArray(product.process)) {
        product.process.forEach(feature => {
          console.log(`  • ${feature}`);
        });
      } else {
        console.log(`  • ${product.process}`);
      }
    }

    // Show TLD info
    if (product.tld) {
      console.log('\n🌐 TLD Information:');
      console.log(`  Extension: ${product.tld}`);
    }

  } else if (product.status === 'unavailable') {
    console.log('❌ Status: UNAVAILABLE (already registered)');

  } else if (product.status === 'pending') {
    console.log('⏳ Status: PENDING (registration in progress)');

  } else if (product.status === 'error') {
    console.log('⚠️  Status: ERROR');
    if (product.message) {
      console.log(`   Message: ${product.message}`);
    }

  } else {
    console.log(`ℹ️  Status: ${product.status}`);
  }

  // Show additional details
  if (product.taxes_included !== undefined) {
    console.log(`\n💵 Taxes included: ${product.taxes_included ? 'Yes' : 'No'}`);
  }

} catch (error) {
  console.error('❌ Error checking domain:', error.message);
  if (error.response) {
    console.error('API Response:', error.response);
  }
  process.exit(1);
}

#!/usr/bin/env node

/**
 * Check SSL Certificates
 * Probes all Gandi domains for SSL/TLS certificates
 * Shows which domains have SSL and which don't
 */

import { listDomains } from './gandi-api.js';
import tls from 'tls';

/**
 * Check if a domain has SSL and get certificate info
 */
async function checkSSL(domain) {
  return new Promise((resolve) => {
    const options = {
      host: domain,
      port: 443,
      servername: domain,
      rejectUnauthorized: false, // Don't fail on self-signed/expired
      timeout: 5000
    };

    const socket = tls.connect(options, () => {
      try {
        const cert = socket.getPeerCertificate();

        if (!cert || Object.keys(cert).length === 0) {
          socket.destroy();
          resolve({
            domain,
            hasSSL: false,
            error: 'No certificate found'
          });
          return;
        }

        // Parse certificate information
        const validFrom = new Date(cert.valid_from);
        const validTo = new Date(cert.valid_to);
        const now = new Date();
        const daysUntilExpiry = Math.ceil((validTo - now) / (1000 * 60 * 60 * 24));
        const isValid = now >= validFrom && now <= validTo;

        // Parse issuer
        let issuer = 'Unknown';
        if (cert.issuer) {
          if (cert.issuer.O) {
            issuer = cert.issuer.O;
          } else if (cert.issuer.CN) {
            issuer = cert.issuer.CN;
          }
        }

        // Simplify common issuer names
        if (issuer.includes('Let\'s Encrypt') || issuer.includes('R3') || issuer.includes('R10')) {
          issuer = 'Let\'s Encrypt';
        } else if (issuer.includes('Google')) {
          issuer = 'Google Trust Services';
        } else if (issuer.includes('Cloudflare')) {
          issuer = 'Cloudflare';
        } else if (issuer.includes('DigiCert')) {
          issuer = 'DigiCert';
        } else if (issuer.includes('Sectigo')) {
          issuer = 'Sectigo';
        } else if (issuer.includes('Gandi')) {
          issuer = 'Gandi';
        }

        socket.destroy();
        resolve({
          domain,
          hasSSL: true,
          issuer,
          validFrom,
          validTo,
          daysUntilExpiry,
          isValid,
          subject: cert.subject?.CN || domain,
          altNames: cert.subjectaltname?.split(', ').map(n => n.replace('DNS:', '')) || []
        });
      } catch (error) {
        socket.destroy();
        resolve({
          domain,
          hasSSL: false,
          error: error.message
        });
      }
    });

    socket.on('error', (error) => {
      resolve({
        domain,
        hasSSL: false,
        error: error.message
      });
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve({
        domain,
        hasSSL: false,
        error: 'Connection timeout'
      });
    });

    socket.setTimeout(5000);
  });
}

console.log('🔒 Checking SSL certificates for all Gandi domains...\n');

try {
  const domains = await listDomains();

  if (!domains || domains.length === 0) {
    console.log('No domains found.');
    process.exit(0);
  }

  console.log(`Probing ${domains.length} domains... (this may take a minute)\n`);

  // Check all domains concurrently (with some throttling)
  const batchSize = 10;
  const results = [];

  for (let i = 0; i < domains.length; i += batchSize) {
    const batch = domains.slice(i, i + batchSize);
    const batchResults = await Promise.all(
      batch.map(d => checkSSL(d.fqdn))
    );
    results.push(...batchResults);
  }

  // Segment results
  const withoutSSL = results.filter(r => !r.hasSSL);
  const withSSL = results.filter(r => r.hasSSL);
  const expired = withSSL.filter(r => !r.isValid && r.daysUntilExpiry < 0);
  const expiringSoon = withSSL.filter(r => r.isValid && r.daysUntilExpiry < 30);

  // Display results
  console.log('═'.repeat(70));
  console.log('RESULTS');
  console.log('═'.repeat(70));
  console.log('');

  // Critical: No SSL
  if (withoutSSL.length > 0) {
    console.log('⚠️  DOMAINS WITHOUT SSL (CRITICAL)');
    console.log('─'.repeat(70));
    withoutSSL.forEach((r, i) => {
      console.log(`${i + 1}. ${r.domain}`);
      console.log(`   Error: ${r.error}`);
      console.log('');
    });
  }

  // Critical: Expired
  if (expired.length > 0) {
    console.log('❌ EXPIRED SSL CERTIFICATES');
    console.log('─'.repeat(70));
    expired.forEach((r, i) => {
      console.log(`${i + 1}. ${r.domain}`);
      console.log(`   Issuer: ${r.issuer}`);
      console.log(`   Expired: ${r.validTo.toDateString()} (${Math.abs(r.daysUntilExpiry)} days ago)`);
      console.log('');
    });
  }

  // Warning: Expiring soon
  if (expiringSoon.length > 0) {
    console.log('⚠️  SSL CERTIFICATES EXPIRING SOON (<30 days)');
    console.log('─'.repeat(70));
    expiringSoon.forEach((r, i) => {
      console.log(`${i + 1}. ${r.domain}`);
      console.log(`   Issuer: ${r.issuer}`);
      console.log(`   Expires: ${r.validTo.toDateString()} (${r.daysUntilExpiry} days)`);
      console.log('');
    });
  }

  // Good: SSL working
  if (withSSL.length > 0) {
    console.log('✅ DOMAINS WITH VALID SSL');
    console.log('─'.repeat(70));

    // Group by issuer
    const byIssuer = {};
    withSSL.filter(r => r.isValid && r.daysUntilExpiry >= 30).forEach(r => {
      if (!byIssuer[r.issuer]) {
        byIssuer[r.issuer] = [];
      }
      byIssuer[r.issuer].push(r);
    });

    Object.keys(byIssuer).sort().forEach(issuer => {
      console.log(`\n${issuer}:`);
      byIssuer[issuer].forEach(r => {
        console.log(`  • ${r.domain}`);
        console.log(`    Expires: ${r.validTo.toDateString()} (${r.daysUntilExpiry} days)`);
      });
    });
    console.log('');
  }

  // Summary
  console.log('═'.repeat(70));
  console.log('SUMMARY');
  console.log('═'.repeat(70));
  console.log(`Total domains: ${domains.length}`);
  console.log(`With SSL: ${withSSL.length}`);
  console.log(`Without SSL: ${withoutSSL.length}`);
  if (expired.length > 0) {
    console.log(`Expired: ${expired.length} ⚠️`);
  }
  if (expiringSoon.length > 0) {
    console.log(`Expiring soon: ${expiringSoon.length} ⚠️`);
  }

  // Issuer breakdown
  if (withSSL.length > 0) {
    console.log('\nCertificate Issuers:');
    const issuerCounts = {};
    withSSL.forEach(r => {
      issuerCounts[r.issuer] = (issuerCounts[r.issuer] || 0) + 1;
    });
    Object.entries(issuerCounts)
      .sort((a, b) => b[1] - a[1])
      .forEach(([issuer, count]) => {
        console.log(`  ${issuer}: ${count}`);
      });
  }

} catch (error) {
  console.log('❌ Error:', error.message);

  if (error.statusCode === 401 || error.statusCode === 403) {
    console.log('\n💡 Authentication error. Run: node test-auth.js');
  }

  process.exit(1);
}

#!/usr/bin/env node

/**
 * Configuration Helper for Gandi Skill
 * Reads from Gateway Console config with fallback to file-based config
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { loadProfiles } from './profile-manager.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const CONFIG_DIR = path.join(process.env.HOME, '.config', 'gandi');
const LEGACY_TOKEN_FILE = path.join(CONFIG_DIR, 'api_token');
const LEGACY_URL_FILE = path.join(CONFIG_DIR, 'api_url');

/**
 * Try to read Gateway config from Clawdbot
 * This assumes Gateway config is available at a standard location
 */
function readGatewayConfig() {
  // Possible Gateway config locations
  const configPaths = [
    path.join(process.env.HOME, '.clawdbot', 'clawdbot.json'),
    path.join(process.env.HOME, '.moltbot', 'moltbot.json'),
    path.join(process.env.HOME, '.config', 'clawdbot', 'config.json'),
  ];

  for (const configPath of configPaths) {
    if (fs.existsSync(configPath)) {
      try {
        const data = fs.readFileSync(configPath, 'utf8');
        const config = JSON.parse(data);

        // Extract Gandi skill config
        const gandiConfig = config.skills?.entries?.gandi?.config;

        if (gandiConfig) {
          return resolveEnvVars(gandiConfig);
        }
      } catch (error) {
        // Ignore parse errors, try next location
        console.warn(`Warning: Could not parse ${configPath}: ${error.message}`);
      }
    }
  }

  return null;
}

/**
 * Resolve environment variable references in config
 * Replaces ${VAR_NAME} with process.env.VAR_NAME
 */
function resolveEnvVars(obj) {
  if (typeof obj === 'string') {
    // Replace ${VAR} with environment variable
    return obj.replace(/\$\{([^}]+)\}/g, (match, varName) => {
      return process.env[varName] || match;
    });
  } else if (Array.isArray(obj)) {
    return obj.map(item => resolveEnvVars(item));
  } else if (obj && typeof obj === 'object') {
    const result = {};
    for (const [key, value] of Object.entries(obj)) {
      result[key] = resolveEnvVars(value);
    }
    return result;
  }
  return obj;
}

/**
 * Get API token from multiple sources (priority order)
 * 1. Gateway config (single token or multi-org)
 * 2. Profile-based config
 * 3. Legacy file-based config
 * 4. Environment variable
 */
export function getApiToken(profileName = null) {
  // 1. Try Gateway config first
  const gatewayConfig = readGatewayConfig();

  if (gatewayConfig) {
    // Multi-org mode
    if (gatewayConfig.organizations && gatewayConfig.organizations.length > 0) {
      let org;

      if (profileName) {
        // Find by profile name
        org = gatewayConfig.organizations.find(o => o.name === profileName);
      } else {
        // Use default org
        org = gatewayConfig.organizations.find(o => o.default);
        if (!org) {
          org = gatewayConfig.organizations[0]; // Fallback to first
        }
      }

      if (org && org.apiToken) {
        return {
          token: org.apiToken,
          sharingId: org.sharingId,
          orgName: org.label || org.name,
          source: 'gateway-multi-org'
        };
      }
    }

    // Single token mode
    if (gatewayConfig.apiToken) {
      return {
        token: gatewayConfig.apiToken,
        source: 'gateway-single'
      };
    }
  }

  // 2. Try profile-based config
  try {
    const profiles = loadProfiles();

    if (Object.keys(profiles.profiles).length > 0) {
      const profile = profileName 
        ? profiles.profiles[profileName]
        : profiles.profiles[profiles.default_profile];

      if (profile) {
        const tokenPath = path.join(CONFIG_DIR, profile.token_file);
        if (fs.existsSync(tokenPath)) {
          const token = fs.readFileSync(tokenPath, 'utf8').trim();
          return {
            token,
            sharingId: profile.org_id,
            orgName: profile.org_name,
            source: 'profile'
          };
        }
      }
    }
  } catch (error) {
    // Profile config not available, continue to legacy
  }

  // 3. Try legacy file-based config
  if (fs.existsSync(LEGACY_TOKEN_FILE)) {
    try {
      const token = fs.readFileSync(LEGACY_TOKEN_FILE, 'utf8').trim();
      if (token) {
        return {
          token,
          source: 'legacy-file'
        };
      }
    } catch (error) {
      // Ignore
    }
  }

  // 4. Try environment variable
  if (process.env.GANDI_API_TOKEN) {
    return {
      token: process.env.GANDI_API_TOKEN,
      source: 'env-var'
    };
  }

  throw new Error('No Gandi API token found. Configure via Gateway Console, profiles, or ~/.config/gandi/api_token');
}

/**
 * Get API URL from config or default
 */
export function getApiUrl() {
  // 1. Gateway config
  const gatewayConfig = readGatewayConfig();
  if (gatewayConfig && gatewayConfig.apiUrl) {
    return gatewayConfig.apiUrl;
  }

  // 2. Legacy file
  if (fs.existsSync(LEGACY_URL_FILE)) {
    try {
      const url = fs.readFileSync(LEGACY_URL_FILE, 'utf8').trim();
      if (url) return url;
    } catch (error) {
      // Ignore
    }
  }

  // 3. Default
  return 'https://api.gandi.net';
}

/**
 * Get domain checker configuration
 */
export function getDomainCheckerConfig() {
  // 1. Gateway config
  const gatewayConfig = readGatewayConfig();
  if (gatewayConfig && gatewayConfig.domainChecker) {
    return gatewayConfig.domainChecker;
  }

  // 2. Legacy file-based config
  const defaultConfigPath = path.join(__dirname, '../config/domain-checker-defaults.json');

  if (fs.existsSync(defaultConfigPath)) {
    try {
      return JSON.parse(fs.readFileSync(defaultConfigPath, 'utf8'));
    } catch (error) {
      console.warn('Warning: Could not read domain checker config:', error.message);
    }
  }

  // 3. Hardcoded defaults
  return {
    tlds: {
      mode: 'extend',
      defaults: ['com', 'net', 'org', 'info', 'io', 'dev', 'app', 'ai', 'tech'],
      custom: []
    },
    variations: {
      enabled: true,
      patterns: ['hyphenated', 'abbreviated', 'prefix', 'suffix', 'numbers'],
      prefixes: ['get', 'my', 'the', 'try'],
      suffixes: ['app', 'hub', 'io', 'ly', 'ai', 'hq'],
      maxNumbers: 3
    },
    rateLimit: {
      maxConcurrent: 3,
      delayMs: 200,
      maxRequestsPerMinute: 100
    },
    limits: {
      maxTlds: 5,
      maxVariations: 10
    }
  };
}

/**
 * List available organizations from config
 */
export function listOrganizations() {
  const gatewayConfig = readGatewayConfig();

  if (gatewayConfig && gatewayConfig.organizations) {
    return gatewayConfig.organizations.map(org => ({
      name: org.name,
      label: org.label || org.name,
      sharingId: org.sharingId,
      default: org.default || false
    }));
  }

  // Fallback to profile-based
  try {
    const profiles = loadProfiles();
    return Object.entries(profiles.profiles).map(([name, profile]) => ({
      name,
      label: profile.org_name,
      sharingId: profile.org_id,
      default: name === profiles.default_profile
    }));
  } catch (error) {
    return [];
  }
}

/**
 * Get configuration summary for diagnostics
 */
export function getConfigSummary() {
  const summary = {
    gatewayConfig: null,
    profileConfig: null,
    legacyFiles: {
      token: fs.existsSync(LEGACY_TOKEN_FILE),
      url: fs.existsSync(LEGACY_URL_FILE)
    },
    envVars: {
      GANDI_API_TOKEN: !!process.env.GANDI_API_TOKEN
    }
  };

  try {
    const gatewayConfig = readGatewayConfig();
    if (gatewayConfig) {
      summary.gatewayConfig = {
        hasApiToken: !!gatewayConfig.apiToken,
        hasOrganizations: !!(gatewayConfig.organizations && gatewayConfig.organizations.length > 0),
        organizationCount: gatewayConfig.organizations?.length || 0,
        hasDomainChecker: !!gatewayConfig.domainChecker
      };
    }
  } catch (error) {
    summary.gatewayConfig = { error: error.message };
  }

  try {
    const profiles = loadProfiles();
    summary.profileConfig = {
      profileCount: Object.keys(profiles.profiles).length,
      defaultProfile: profiles.default_profile,
      profiles: Object.keys(profiles.profiles)
    };
  } catch (error) {
    summary.profileConfig = { error: error.message };
  }

  return summary;
}

