#!/usr/bin/env node

/**
 * List SSL/TLS certificates managed by Gandi
 * 
 * Note: This lists certificates requested/managed through Gandi's certificate API,
 * not external certificates. Use check-ssl.js to probe actual certificate status.
 * 
 * Usage:
 *   node list-certificates.js
 */

import { listCertificates } from './gandi-api.js';

// Format date nicely
function formatDate(dateString) {
  if (!dateString) return 'N/A';
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', { 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });
}

// Main function
async function main() {
  try {
    console.log('🔒 Listing SSL/TLS certificates managed by Gandi...');
    console.log('');

    const certificates = await listCertificates();

    if (!certificates || certificates.length === 0) {
      console.log('📭 No certificates found.');
      console.log('');
      console.log('💡 This lists certificates managed through Gandi\'s certificate API.');
      console.log('   External certificates or Let\'s Encrypt certificates managed');
      console.log('   outside of Gandi won\'t appear here.');
      console.log('');
      console.log('📊 To check actual SSL status of your domains:');
      console.log('   node check-ssl.js');
      console.log('');
      console.log('💡 To request a new certificate:');
      console.log('   node request-certificate.js example.com');
      return;
    }

    console.log(`📋 Certificates (${certificates.length} total):`);
    console.log('');

    certificates.forEach((cert, index) => {
      console.log(`${index + 1}. ${cert.cn || 'Unknown CN'}`);

      if (cert.id || cert.uuid) {
        console.log(`   ID: ${cert.id || cert.uuid}`);
      }

      if (cert.status) {
        const statusEmoji = {
          'valid': '✅',
          'pending': '⏳',
          'expired': '❌',
          'revoked': '🚫'
        };
        console.log(`   Status: ${statusEmoji[cert.status] || '❓'} ${cert.status.toUpperCase()}`);
      }

      if (cert.alt_names && cert.alt_names.length > 0) {
        console.log(`   SANs: ${cert.alt_names.join(', ')}`);
      }

      if (cert.dates) {
        if (cert.dates.created_at) {
          console.log(`   Created: ${formatDate(cert.dates.created_at)}`);
        }
        if (cert.dates.valid_from) {
          console.log(`   Valid From: ${formatDate(cert.dates.valid_from)}`);
        }
        if (cert.dates.valid_to) {
          console.log(`   Expires: ${formatDate(cert.dates.valid_to)}`);

          // Calculate days until expiry
          const validTo = new Date(cert.dates.valid_to);
          const now = new Date();
          const daysUntilExpiry = Math.ceil((validTo - now) / (1000 * 60 * 60 * 24));

          if (daysUntilExpiry < 0) {
            console.log(`   ❌ Expired ${Math.abs(daysUntilExpiry)} days ago`);
          } else if (daysUntilExpiry < 30) {
            console.log(`   ⚠️  Expires in ${daysUntilExpiry} days`);
          } else {
            console.log(`   ✅ ${daysUntilExpiry} days remaining`);
          }
        }
      }

      if (cert.package) {
        console.log(`   Type: ${cert.package}`);
      }

      if (cert.dcv_method) {
        console.log(`   Validation: ${cert.dcv_method}`);
      }

      if (cert.auto_renew !== undefined) {
        console.log(`   Auto-renew: ${cert.auto_renew ? '✅ Enabled' : '❌ Disabled'}`);
      }

      console.log('');
    });

    console.log('💡 To view certificate details:');
    console.log('   node cert-details.js <certificate-id>');
    console.log('');
    console.log('💡 To request a new certificate:');
    console.log('   node request-certificate.js example.com');
    console.log('');
    console.log('📊 To check actual SSL status of all domains:');
    console.log('   node check-ssl.js');

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('');
      console.error('Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('');
      console.error('Permission denied. Possible causes:');
      console.error('  - API token lacks required scopes');
      console.error('  - Certificate management not available for your account');
      console.error('');
      console.error('💡 This feature may require a Gandi SSL certificate subscription.');
    } else if (error.statusCode === 404) {
      console.error('');
      console.error('Certificate API endpoint not found.');
      console.error('This feature may not be available or may require different permissions.');
    } else if (error.response) {
      console.error('API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * List DNS Records
 * Shows DNS records for a domain
 * 
 * Usage: node list-dns.js <domain>
 */

import { listDnsRecords, getDomain, sanitizeDomain } from './gandi-api.js';

const rawDomain = process.argv[2];

if (!rawDomain) {
  console.log('Usage: node list-dns.js <domain>');
  console.log('Example: node list-dns.js example.com');
  process.exit(1);
}

// Sanitize domain input for security
let domain;
try {
  domain = sanitizeDomain(rawDomain);
} catch (error) {
  console.error(`❌ Invalid domain: ${error.message}`);
  process.exit(1);
}

console.log(`🔍 Fetching DNS records for ${domain}...\n`);

try {
  // First verify domain exists and uses LiveDNS
  let domainInfo;
  try {
    domainInfo = await getDomain(domain);
  } catch (error) {
    if (error.statusCode === 404) {
      console.log(`❌ Domain "${domain}" not found in your account.`);
      console.log('\n💡 Run: node list-domains.js');
      process.exit(1);
    }
    throw error;
  }

  // Check if using LiveDNS
  if (!domainInfo.services || !domainInfo.services.includes('gandilivedns')) {
    console.log(`⚠️  Domain "${domain}" is not using Gandi LiveDNS.`);
    console.log('\nCurrent services:', domainInfo.services?.join(', ') || 'none');
    console.log('\n💡 To use LiveDNS, attach it in Gandi admin panel.');
    process.exit(1);
  }

  // Get DNS records
  const records = await listDnsRecords(domain);

  if (!records || records.length === 0) {
    console.log('No DNS records found.');
    process.exit(0);
  }

  console.log(`Found ${records.length} DNS record${records.length === 1 ? '' : 's'}:\n`);

  // Group by type for better display
  const recordsByType = {};
  records.forEach(record => {
    if (!recordsByType[record.rrset_type]) {
      recordsByType[record.rrset_type] = [];
    }
    recordsByType[record.rrset_type].push(record);
  });

  // Display records grouped by type
  Object.keys(recordsByType).sort().forEach(type => {
    console.log(`\n${type} Records:`);
    console.log('─'.repeat(50));

    recordsByType[type].forEach(record => {
      const name = record.rrset_name === '@' ? '@ (root)' : record.rrset_name;
      const ttl = record.rrset_ttl || 10800;
      const ttlStr = formatTTL(ttl);

      console.log(`  ${name}`);
      console.log(`    TTL: ${ttlStr}`);

      if (record.rrset_values && record.rrset_values.length > 0) {
        record.rrset_values.forEach((value, index) => {
          const prefix = index === 0 ? '    →' : '     ';
          console.log(`${prefix} ${value}`);
        });
      }

      console.log('');
    });
  });

  // Summary
  console.log('\n' + '═'.repeat(50));
  console.log(`Total: ${records.length} record${records.length === 1 ? '' : 's'} across ${Object.keys(recordsByType).length} type${Object.keys(recordsByType).length === 1 ? '' : 's'}`);

  // Show nameservers from domain info
  if (domainInfo.nameservers && domainInfo.nameservers.length > 0) {
    console.log('\nNameservers:');
    domainInfo.nameservers.forEach(ns => {
      console.log(`  • ${ns}`);
    });
  }

} catch (error) {
  console.log('❌ Error:', error.message);

  if (error.statusCode === 401 || error.statusCode === 403) {
    console.log('\n💡 Authentication error. Run: node test-auth.js');
  } else if (error.statusCode === 404) {
    console.log('\n💡 Domain not found. Check spelling or run: node list-domains.js');
  }

  process.exit(1);
}

/**
 * Format TTL value in human-readable form
 */
function formatTTL(seconds) {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m (${seconds}s)`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h (${seconds}s)`;
  return `${Math.floor(seconds / 86400)}d (${seconds}s)`;
}

#!/usr/bin/env node

/**
 * List Domains
 * Shows all domains in your Gandi account
 */

import { listDomains } from './gandi-api.js';

console.log('🌐 Listing your Gandi domains...\n');

try {
  const domains = await listDomains();

  if (!domains || domains.length === 0) {
    console.log('No domains found in your account.');
    console.log('\nYou can register domains at: https://www.gandi.net');
    process.exit(0);
  }

  console.log(`Found ${domains.length} domain${domains.length === 1 ? '' : 's'}:\n`);

  domains.forEach((domain, index) => {
    console.log(`${index + 1}. ${domain.fqdn}`);

    if (domain.fqdn_unicode !== domain.fqdn) {
      console.log(`   Unicode: ${domain.fqdn_unicode}`);
    }

    // Status
    if (domain.status && domain.status.length > 0) {
      console.log(`   Status: ${domain.status.join(', ')}`);
    }

    // Expiration
    if (domain.dates && domain.dates.registry_ends_at) {
      const expiresAt = new Date(domain.dates.registry_ends_at);
      const now = new Date();
      const daysUntilExpiry = Math.ceil((expiresAt - now) / (1000 * 60 * 60 * 24));

      console.log(`   Expires: ${expiresAt.toDateString()} (${daysUntilExpiry} days)`);

      if (daysUntilExpiry < 30) {
        console.log(`   ⚠️  Expires soon!`);
      }
    }

    // Auto-renewal (can be boolean or object depending on API response)
    if (domain.autorenew !== undefined) {
      const enabled = typeof domain.autorenew === 'boolean' 
        ? domain.autorenew 
        : domain.autorenew.enabled;
      const status = enabled ? '✅ Enabled' : '❌ Disabled';
      console.log(`   Auto-renew: ${status}`);
    }

    // Services
    if (domain.services && domain.services.length > 0) {
      const serviceNames = domain.services
        .map(s => {
          if (s === 'gandilivedns') return 'LiveDNS';
          if (s === 'mailboxv2') return 'Email';
          return s;
        })
        .join(', ');
      console.log(`   Services: ${serviceNames}`);
    }

    // Organization
    if (domain.sharing_space && domain.sharing_space.name) {
      console.log(`   Organization: ${domain.sharing_space.name}`);
    }

    console.log('');
  });

  // Summary
  const expiringSoon = domains.filter(d => {
    if (!d.dates || !d.dates.registry_ends_at) return false;
    const expiresAt = new Date(d.dates.registry_ends_at);
    const now = new Date();
    const days = Math.ceil((expiresAt - now) / (1000 * 60 * 60 * 24));
    return days < 30;
  });

  if (expiringSoon.length > 0) {
    console.log(`⚠️  ${expiringSoon.length} domain${expiringSoon.length === 1 ? '' : 's'} expiring within 30 days!`);
  }

  const withoutAutorenew = domains.filter(d => {
    if (d.autorenew === undefined) return true; // No autorenew data = disabled
    const enabled = typeof d.autorenew === 'boolean' 
      ? d.autorenew 
      : d.autorenew.enabled;
    return !enabled;
  });
  if (withoutAutorenew.length > 0) {
    console.log(`💡 ${withoutAutorenew.length} domain${withoutAutorenew.length === 1 ? '' : 's'} without auto-renewal`);
  }

} catch (error) {
  console.log('❌ Error:', error.message);

  if (error.statusCode === 401 || error.statusCode === 403) {
    console.log('\n💡 Authentication error. Run: node test-auth.js');
  }

  process.exit(1);
}

