} catch (error) {
  console.error(`❌ Invalid domain: ${error.message}`);
  process.exit(1);
}

async function main() {
  try {
    console.log(`📸 Fetching snapshots for ${domain}...`);
    console.log('');

    const snapshots = await listSnapshots(domain);

    if (!snapshots || snapshots.length === 0) {
      console.log('ℹ️  No snapshots found for this domain.');
      console.log('');
      console.log('💡 Create a snapshot with:');
      console.log(`   node create-snapshot.js ${domain} "Snapshot name"`);
      return;
    }

    console.log(`Found ${snapshots.length} snapshot(s):\n`);

    snapshots.forEach((snapshot, index) => {
      const createdDate = new Date(snapshot.created_at);
      const isAutomatic = snapshot.automatic ? ' (automatic)' : '';

      console.log(`${index + 1}. ${snapshot.name}${isAutomatic}`);
      console.log(`   ID: ${snapshot.uuid || snapshot.id}`);
      console.log(`   Created: ${createdDate.toLocaleString()}`);
      console.log(`   Records: ${snapshot.zone_data?.length || 'unknown'}`);
      console.log('');
    });

    console.log('💡 To restore a snapshot:');
    console.log(`   node restore-snapshot.js ${domain} <snapshot-id>`);

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('   Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('   Permission denied. Ensure your token has LiveDNS read access.');
    } else if (error.statusCode === 404) {
      console.error(`   Domain ${domain} not found or not using Gandi LiveDNS.`);
    } else if (error.response) {
      console.error('   API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Manage Gandi organization profiles
 * 
 * Usage:
 *   node manage-profiles.js <action> [options]
 * 
 * Actions:
 *   list                          - List all profiles
 *   add <name> <token>            - Add a new profile
 *   remove <name>                 - Remove a profile
 *   default <name>                - Set default profile
 *   show <name>                   - Show profile details
 *   migrate                       - Migrate legacy token to profile
 * 
 * Examples:
 *   node manage-profiles.js list
 *   node manage-profiles.js add personal YOUR_TOKEN
 *   node manage-profiles.js add work YOUR_TOKEN --set-default
 *   node manage-profiles.js default personal
 *   node manage-profiles.js remove old-profile
 */

import {
  listProfiles,
  addProfile,
  removeProfile,
  setDefaultProfile,
  getProfile,
  migrateLegacyToken
} from './profile-manager.js';

// Parse command line arguments
const args = process.argv.slice(2);

if (args.length < 1) {
  console.error('Usage: node manage-profiles.js <action> [options]');
  console.error('');
  console.error('Actions:');
  console.error('  list                          - List all profiles');
  console.error('  add <name> <token>            - Add a new profile');
  console.error('  remove <name>                 - Remove a profile');
  console.error('  default <name>                - Set default profile');
  console.error('  show <name>                   - Show profile details');
  console.error('  migrate                       - Migrate legacy token');
  console.error('');
  console.error('Examples:');
  console.error('  node manage-profiles.js list');
  console.error('  node manage-profiles.js add personal YOUR_TOKEN');
  console.error('  node manage-profiles.js add work YOUR_TOKEN --set-default');
  console.error('  node manage-profiles.js default personal');
  console.error('  node manage-profiles.js show personal');
  process.exit(1);
}

const action = args[0];

// List profiles
async function listAction() {
  console.log('📋 Gandi Organization Profiles');
  console.log('');

  const { profiles, default: defaultProfile } = listProfiles();

  if (Object.keys(profiles).length === 0) {
    console.log('No profiles configured.');
    console.log('');
    console.log('💡 To add a profile:');
    console.log('   node manage-profiles.js add <name> <token>');
    console.log('');
    console.log('📝 Get your Personal Access Token at:');
    console.log('   https://admin.gandi.net/organizations/account/pat');
    return;
  }

  Object.entries(profiles).forEach(([name, profile]) => {
    const isDefault = name === defaultProfile;
    console.log(`${isDefault ? '✅' : '  '} ${name}`);
    console.log(`   Organization: ${profile.org_name} (${profile.org_type})`);
    console.log(`   ID: ${profile.org_id}`);
    console.log(`   Token: ${profile.token_file}`);
    console.log('');
  });

  if (defaultProfile) {
    console.log(`Default profile: ${defaultProfile} ✅`);
  } else {
    console.log('⚠️  No default profile set');
  }

  console.log('');
  console.log('💡 To use a specific profile:');
  console.log('   Use --profile <name> flag with any command');
  console.log('   Example: node list-domains.js --profile work');
}

// Add profile
async function addAction(name, token, setDefault = false) {
  if (!name || !token) {
    console.error('❌ Usage: node manage-profiles.js add <name> <token>');
    process.exit(1);
  }

  console.log(`📝 Adding profile "${name}"...`);
  console.log('');

  try {
    const profile = await addProfile(name, token, { setDefault });

    console.log('✅ Profile added successfully!');
    console.log('');
    console.log(`   Name: ${name}`);
    console.log(`   Organization: ${profile.org_name}`);
    console.log(`   Type: ${profile.org_type}`);
    console.log(`   ID: ${profile.org_id}`);

    if (setDefault) {
      console.log('   ✅ Set as default profile');
    }

    console.log('');
    console.log('💡 To use this profile:');
    console.log(`   node list-domains.js --profile ${name}`);
    console.log('');
    console.log('💡 To set as default:');
    console.log(`   node manage-profiles.js default ${name}`);

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Remove profile
async function removeAction(name) {
  if (!name) {
    console.error('❌ Usage: node manage-profiles.js remove <name>');
    process.exit(1);
  }

  console.log(`🗑️  Removing profile "${name}"...`);
  console.log('');

  try {
    removeProfile(name);

    console.log('✅ Profile removed successfully!');
    console.log('');
    console.log('📋 To see remaining profiles:');
    console.log('   node manage-profiles.js list');

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Set default profile
async function defaultAction(name) {
  if (!name) {
    console.error('❌ Usage: node manage-profiles.js default <name>');
    process.exit(1);
  }

  console.log(`⚙️  Setting default profile to "${name}"...`);
  console.log('');

  try {
    setDefaultProfile(name);

    console.log('✅ Default profile updated!');
    console.log('');
    console.log(`   All commands will now use the "${name}" profile by default`);
    console.log('   unless you specify --profile <other-name>');

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Show profile details
async function showAction(name) {
  if (!name) {
    console.error('❌ Usage: node manage-profiles.js show <name>');
    process.exit(1);
  }

  try {
    const profile = getProfile(name);
    const { default: defaultProfile } = listProfiles();

    console.log(`📋 Profile: ${name}`);
    console.log('');
    console.log(`   Organization: ${profile.org_name}`);
    console.log(`   Type: ${profile.org_type}`);
    console.log(`   ID: ${profile.org_id}`);
    console.log(`   Token File: ${profile.token_file}`);

    if (name === defaultProfile) {
      console.log(`   Status: ✅ Default profile`);
    }

    console.log('');
    console.log('💡 To use this profile:');
    console.log(`   node list-domains.js --profile ${name}`);

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Migrate legacy token
async function migrateAction() {
  console.log('📦 Checking for legacy token...');
  console.log('');

  try {
    const result = await migrateLegacyToken();

    if (!result) {
      console.log('ℹ️  No legacy token found or profiles already exist.');
      console.log('');
      console.log('💡 To add a profile manually:');
      console.log('   node manage-profiles.js add <name> <token>');
    }

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Main function
async function main() {
  try {
    switch (action.toLowerCase()) {
      case 'list':
        await listAction();
        break;

      case 'add':
        const name = args[1];
        const token = args[2];
        const setDefault = args.includes('--set-default');
        await addAction(name, token, setDefault);
        break;

      case 'remove':
      case 'delete':
        await removeAction(args[1]);
        break;

      case 'default':
      case 'set-default':
        await defaultAction(args[1]);
        break;

      case 'show':
      case 'info':
        await showAction(args[1]);
        break;

      case 'migrate':
        await migrateAction();
        break;

      default:
        console.error(`❌ Unknown action: ${action}`);
        console.error('Valid actions: list, add, remove, default, show, migrate');
        process.exit(1);
    }

  } catch (error) {
    console.error('❌ Unexpected error:', error.message);
    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Manage DNS zone snapshots
 * 
 * Usage:
 *   node manage-snapshots.js <domain> list
 *   node manage-snapshots.js <domain> create <name>
 *   node manage-snapshots.js <domain> restore <snapshot-id> [--confirm]
 * 
 * Examples:
 *   node manage-snapshots.js example.com list
 *   node manage-snapshots.js example.com create "Before DNS migration"
 *   node manage-snapshots.js example.com restore abc123 --confirm
 */

import {
  listSnapshots,
  createSnapshot,
  restoreSnapshot,
  listDnsRecords
} from './gandi-api.js';
import readline from 'readline';

// Parse command line arguments
const args = process.argv.slice(2);

if (args.length < 2) {
  console.error('Usage: node manage-snapshots.js <domain> <action> [options]');
  console.error('');
  console.error('Actions:');
  console.error('  list                    - List all snapshots');
  console.error('  create <name>           - Create a new snapshot');
  console.error('  restore <id> [--confirm] - Restore from snapshot');
  console.error('');
  console.error('Examples:');
  console.error('  node manage-snapshots.js example.com list');
  console.error('  node manage-snapshots.js example.com create "Before migration"');
  console.error('  node manage-snapshots.js example.com restore abc123 --confirm');
  process.exit(1);
}

const domain = args[0];
const action = args[1];

// Prompt for confirmation
function confirm(message) {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    rl.question(message, (answer) => {
      rl.close();
      resolve(answer.toLowerCase().startsWith('y'));
    });
  });
}

// List snapshots
async function listAction() {
  console.log(`📸 Snapshots for ${domain}`);
  console.log('');

  try {
    const snapshots = await listSnapshots(domain);

    if (!snapshots || snapshots.length === 0) {
      console.log('No snapshots found.');
      console.log('');
      console.log('💡 Create a snapshot with:');
      console.log(`   node manage-snapshots.js ${domain} create "My snapshot"`);
      return;
    }

    console.log(`Found ${snapshots.length} snapshot(s):`);
    console.log('');

    snapshots.forEach((snapshot, index) => {
      console.log(`${index + 1}. ${snapshot.name || 'Unnamed snapshot'}`);
      console.log(`   ID: ${snapshot.id || snapshot.uuid}`);
      if (snapshot.created_at) {
        const date = new Date(snapshot.created_at);
        console.log(`   Created: ${date.toLocaleString()}`);
      }
      if (snapshot.automatic !== undefined) {
        console.log(`   Type: ${snapshot.automatic ? 'Automatic' : 'Manual'}`);
      }
      console.log('');
    });

    console.log('💡 To restore a snapshot:');
    console.log(`   node manage-snapshots.js ${domain} restore <snapshot-id> --confirm`);

  } catch (error) {
    console.error('❌ Error:', error.message);
    if (error.statusCode === 404) {
      console.error('Domain not found or not using Gandi LiveDNS.');
    }
    process.exit(1);
  }
}

// Create snapshot
async function createAction(name) {
  if (!name) {
    console.error('❌ Error: Snapshot name required');
    console.error('Usage: node manage-snapshots.js <domain> create <name>');
    process.exit(1);
  }

  console.log(`📸 Creating snapshot for ${domain}`);
  console.log(`   Name: ${name}`);
  console.log('');

  try {
    const snapshot = await createSnapshot(domain, name);
    console.log('✅ Snapshot created successfully!');
    console.log(`   ID: ${snapshot.id || snapshot.uuid || 'N/A'}`);
    console.log('');
    console.log('💡 To restore this snapshot later:');
    console.log(`   node manage-snapshots.js ${domain} restore ${snapshot.id || snapshot.uuid} --confirm`);

  } catch (error) {
    console.error('❌ Error:', error.message);
    if (error.statusCode === 403) {
      console.error('Permission denied. Ensure your API token has LiveDNS: write scope.');
    } else if (error.statusCode === 404) {
      console.error('Domain not found or not using Gandi LiveDNS.');
    }
    process.exit(1);
  }
}

// Restore snapshot
async function restoreAction(snapshotId, autoConfirm) {
  if (!snapshotId) {
    console.error('❌ Error: Snapshot ID required');
    console.error('Usage: node manage-snapshots.js <domain> restore <snapshot-id> [--confirm]');
    console.error('');
    console.error('💡 List available snapshots:');
    console.error(`   node manage-snapshots.js ${domain} list`);
    process.exit(1);
  }

  console.log(`🔄 Restoring ${domain} from snapshot`);
  console.log(`   Snapshot ID: ${snapshotId}`);
  console.log('');

  try {
    // Show current DNS records
    console.log('📋 Current DNS records will be replaced...');
    const currentRecords = await listDnsRecords(domain);
    console.log(`   Currently: ${currentRecords.length} record(s)`);
    console.log('');

    // Warn about replacement
    console.log('⚠️  WARNING: This will REPLACE all current DNS records!');
    console.log('All changes made after the snapshot was created will be lost.');
    console.log('');

    // Confirm restore
    if (!autoConfirm) {
      const confirmed = await confirm('Are you sure you want to restore this snapshot? (yes/no): ');

      if (!confirmed) {
        console.log('❌ Restore cancelled.');
        process.exit(0);
      }
      console.log('');
    }

    // Restore the snapshot
    console.log('🔄 Restoring...');
    await restoreSnapshot(domain, snapshotId);

    console.log('✅ Snapshot restored successfully!');
    console.log('');
    console.log('⏱️  DNS Propagation:');
    console.log('   - Gandi nameservers: immediate');
    console.log('   - Local cache: ~5 minutes');
    console.log('   - Global: 24-48 hours (worst case)');
    console.log('');
    console.log('🔍 Verify your DNS records:');
    console.log(`   node list-dns.js ${domain}`);

  } catch (error) {
    console.error('❌ Error:', error.message);
    if (error.statusCode === 403) {
      console.error('Permission denied. Ensure your API token has LiveDNS: write scope.');
    } else if (error.statusCode === 404) {
      console.error('Snapshot or domain not found.');
    }
    process.exit(1);
  }
}

// Main function
async function main() {
  try {
    switch (action) {
      case 'list':
        await listAction();
        break;

      case 'create':
        const name = args.slice(2).join(' ');
        await createAction(name);
        break;

      case 'restore':
        const snapshotId = args[2];
        const autoConfirm = args.includes('--confirm');
        await restoreAction(snapshotId, autoConfirm);
        break;

      default:
        console.error(`❌ Unknown action: ${action}`);
        console.error('Valid actions: list, create, restore');
        process.exit(1);
    }

  } catch (error) {
    console.error('❌ Unexpected error:', error.message);
    process.exit(1);
  }
}

main();

