#!/usr/bin/env node

/**
 * Profile Manager for Multi-Organization Support
 * Manages multiple Gandi organization profiles with separate tokens
 */

import fs from 'fs';
import path from 'path';
import { gandiApi } from './gandi-api.js';

const CONFIG_DIR = path.join(process.env.HOME, '.config', 'gandi');
const PROFILES_FILE = path.join(CONFIG_DIR, 'profiles.json');
const TOKENS_DIR = path.join(CONFIG_DIR, 'tokens');
const LEGACY_TOKEN_FILE = path.join(CONFIG_DIR, 'api_token');

/**
 * Ensure config directories exist
 */
function ensureConfigDirs() {
  if (!fs.existsSync(CONFIG_DIR)) {
    fs.mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 });
  }
  if (!fs.existsSync(TOKENS_DIR)) {
    fs.mkdirSync(TOKENS_DIR, { recursive: true, mode: 0o700 });
  }
}

/**
 * Load profiles configuration
 */
export function loadProfiles() {
  ensureConfigDirs();

  if (!fs.existsSync(PROFILES_FILE)) {
    return {
      profiles: {},
      default_profile: null
    };
  }

  try {
    const data = fs.readFileSync(PROFILES_FILE, 'utf8');
    return JSON.parse(data);
  } catch (error) {
    throw new Error(`Failed to load profiles: ${error.message}`);
  }
}

/**
 * Save profiles configuration
 */
export function saveProfiles(config) {
  ensureConfigDirs();

  try {
    fs.writeFileSync(PROFILES_FILE, JSON.stringify(config, null, 2), { mode: 0o600 });
  } catch (error) {
    throw new Error(`Failed to save profiles: ${error.message}`);
  }
}

/**
 * Get profile by name
 */
export function getProfile(name) {
  const config = loadProfiles();

  if (!name) {
    name = config.default_profile;
  }

  if (!name) {
    throw new Error('No profile specified and no default profile set');
  }

  const profile = config.profiles[name];

  if (!profile) {
    throw new Error(`Profile '${name}' not found`);
  }

  return profile;
}

/**
 * Read token for a profile
 */
export function readProfileToken(profileName) {
  const profile = getProfile(profileName);
  const tokenPath = path.join(CONFIG_DIR, profile.token_file);

  if (!fs.existsSync(tokenPath)) {
    throw new Error(`Token file not found for profile '${profileName}': ${tokenPath}`);
  }

  try {
    const token = fs.readFileSync(tokenPath, 'utf8').trim();

    if (!token) {
      throw new Error(`Token file is empty for profile '${profileName}'`);
    }

    return token;
  } catch (error) {
    throw new Error(`Failed to read token for profile '${profileName}': ${error.message}`);
  }
}

/**
 * List all profiles
 */
export function listProfiles() {
  const config = loadProfiles();
  return {
    profiles: config.profiles,
    default: config.default_profile
  };
}

/**
 * Add a new profile
 */
export async function addProfile(name, token, options = {}) {
  ensureConfigDirs();

  const config = loadProfiles();

  // Check if profile already exists
  if (config.profiles[name]) {
    throw new Error(`Profile '${name}' already exists`);
  }

  // Save token to file
  const tokenFile = `tokens/${name}.token`;
  const tokenPath = path.join(CONFIG_DIR, tokenFile);
  fs.writeFileSync(tokenPath, token, { mode: 0o600 });

  // Fetch organization info
  let orgInfo;
  try {
    // Temporarily use this token to fetch org info
    const result = await gandiApi('/v5/organization/organizations', 'GET', null, {}, token);
    orgInfo = result.data[0]; // Use first org
  } catch (error) {
    // Clean up token file on error
    fs.unlinkSync(tokenPath);
    throw new Error(`Failed to fetch organization info: ${error.message}`);
  }

  // Create profile
  config.profiles[name] = {
    token_file: tokenFile,
    org_id: orgInfo.id,
    org_name: orgInfo.name || orgInfo.id,
    org_type: orgInfo.type || 'unknown'
  };

  // Set as default if it's the first profile or explicitly requested
  if (Object.keys(config.profiles).length === 1 || options.setDefault) {
    config.default_profile = name;
  }

  saveProfiles(config);

  return config.profiles[name];
}

/**
 * Remove a profile
 */
export function removeProfile(name) {
  const config = loadProfiles();

  if (!config.profiles[name]) {
    throw new Error(`Profile '${name}' not found`);
  }

  // Delete token file
  const tokenPath = path.join(CONFIG_DIR, config.profiles[name].token_file);
  if (fs.existsSync(tokenPath)) {
    fs.unlinkSync(tokenPath);
  }

  // Remove profile
  delete config.profiles[name];

  // Update default if needed
  if (config.default_profile === name) {
    const remaining = Object.keys(config.profiles);
    config.default_profile = remaining.length > 0 ? remaining[0] : null;
  }

  saveProfiles(config);
}

/**
 * Set default profile
 */
export function setDefaultProfile(name) {
  const config = loadProfiles();

  if (!config.profiles[name]) {
    throw new Error(`Profile '${name}' not found`);
  }

  config.default_profile = name;
  saveProfiles(config);
}

/**
 * Migrate legacy single token to profile
 */
export async function migrateLegacyToken() {
  if (!fs.existsSync(LEGACY_TOKEN_FILE)) {
    return null;
  }

  const config = loadProfiles();

  // Don't migrate if profiles already exist
  if (Object.keys(config.profiles).length > 0) {
    return null;
  }

  console.log('📦 Migrating legacy token to profile system...');

  try {
    const token = fs.readFileSync(LEGACY_TOKEN_FILE, 'utf8').trim();

    // Create default profile
    await addProfile('default', token, { setDefault: true });

    // Rename legacy file as backup
    fs.renameSync(LEGACY_TOKEN_FILE, `${LEGACY_TOKEN_FILE}.backup`);

    console.log('✅ Migration complete! Legacy token backed up.');
    console.log('   Profile "default" created.');
    console.log('');

    return 'default';
  } catch (error) {
    console.error(`⚠️  Migration failed: ${error.message}`);
    return null;
  }
}

// Update gandiApi to support token override
export function gandiApiWithToken(endpoint, method, data, queryParams, token) {
  return gandiApi(endpoint, method, data, queryParams, token);
}

#!/usr/bin/env node

/**
 * Register a new domain via Gandi Domain API
 * 
 * ⚠️  WARNING: Domain registration costs real money and is NON-REFUNDABLE!
 * 
 * Usage:
 *   node register-domain.js <domain> [options]
 * 
 * Options:
 *   --years <n>              Registration duration (1-10 years, default: 1)
 *   --contact <file>         JSON file with contact info (optional if setup-contact.js run)
 *   --auto-renew             Enable auto-renewal
 *   --purge-contact          Delete saved contact after registration (privacy option)
 *   --dry-run                Check availability and show cost without registering
 * 
 * Examples:
 *   node register-domain.js example.com --dry-run
 *   node register-domain.js example.com --years 1 --auto-renew  (uses saved contact)
 *   node register-domain.js example.com --years 2 --contact owner.json  (custom contact)
 *   node register-domain.js example.com --years 1 --purge-contact  (delete contact after)
 * 
 * Setup:
 *   node setup-contact.js    Save contact info for reuse (run once)
 *   node delete-contact.js   Delete saved contact manually
 */

import {
  checkAvailability,
  registerDomain,
  validateContact,
  setAutoRenewal,
  loadSavedContact
} from './gandi-api.js';
import fs from 'fs';
import path from 'path';
import os from 'os';
import readline from 'readline';

const CONTACT_FILE = path.join(os.homedir(), '.config', 'gandi', 'contact.json');

// Parse command line arguments
const args = process.argv.slice(2);

if (args.length < 1) {
  console.error('Usage: node register-domain.js <domain> [options]');
  console.error('');
  console.error('Options:');
  console.error('  --years <n>              Registration duration (1-10 years, default: 1)');
  console.error('  --contact <file>         JSON file with contact info (optional if setup-contact.js run)');
  console.error('  --auto-renew             Enable auto-renewal');
  console.error('  --purge-contact          Delete saved contact after registration (privacy option)');
  console.error('  --dry-run                Check and show cost without registering');
  console.error('');
  console.error('⚠️  WARNING: Domain registration costs real money and is NON-REFUNDABLE!');
  console.error('');
  console.error('Examples:');
  console.error('  node register-domain.js example.com --dry-run');
  console.error('  node register-domain.js example.com --years 1 --auto-renew  (uses saved contact)');
  console.error('  node register-domain.js example.com --years 2 --contact owner.json  (custom)');
  console.error('  node register-domain.js example.com --years 1 --purge-contact  (delete after)');
  console.error('');
  console.error('Setup (run once):');
  console.error('  node setup-contact.js    Save contact info for reuse');
  console.error('  node delete-contact.js   Delete saved contact manually');
  console.error('');
  console.error('Contact JSON format (if not using setup-contact.js):');
  console.error('  {');
  console.error('    "given": "John",');
  console.error('    "family": "Doe",');
  console.error('    "email": "john@example.com",');
  console.error('    "streetaddr": "123 Main St",');
  console.error('    "city": "Paris",');
  console.error('    "state": "US-CA",');
  console.error('    "zip": "75001",');
  console.error('    "country": "US",');
  console.error('    "phone": "+1.5551234567",');
  console.error('    "type": "individual"');
  console.error('  }');
  process.exit(1);
}

const domain = args[0];
let years = 1;
let contactFile = null;
let autoRenew = false;
let dryRun = false;
let purgeContact = false;

// Parse options
for (let i = 1; i < args.length; i++) {
  if (args[i] === '--years' && args[i + 1]) {
    years = parseInt(args[i + 1], 10);
    i++;
  } else if (args[i] === '--contact' && args[i + 1]) {
    contactFile = args[i + 1];
    i++;
  } else if (args[i] === '--auto-renew') {
    autoRenew = true;
  } else if (args[i] === '--dry-run') {
    dryRun = true;
  } else if (args[i] === '--purge-contact') {
    purgeContact = true;
  }
}

// Validate years
if (isNaN(years) || years < 1 || years > 10) {
  console.error('❌ Error: Years must be between 1 and 10');
  process.exit(1);
}

// Prompt for confirmation
function confirm(message) {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    rl.question(message, (answer) => {
      rl.close();
      resolve(answer.toLowerCase() === 'yes');
    });
  });
}

// Main function
async function main() {
  try {
    console.log('🔍 Checking domain availability...');
    console.log('');

    // Check availability
    const availability = await checkAvailability([domain]);
    const domainInfo = availability.products?.[0];

    if (!domainInfo) {
      console.error('❌ Error: Could not retrieve domain information');
      process.exit(1);
    }

    // Check if available
    if (domainInfo.status !== 'available') {
      console.error(`❌ Domain ${domain} is NOT available for registration`);
      console.error(`   Status: ${domainInfo.status}`);

      if (domainInfo.status === 'unavailable') {
        console.error('   This domain is already registered.');
      } else if (domainInfo.status === 'pending') {
        console.error('   This domain has a pending registration.');
      }

      process.exit(1);
    }

    console.log(`✅ ${domain} is AVAILABLE!`);
    console.log('');

    // Show pricing
    const prices = domainInfo.prices || [];
    const yearPrice = prices.find(p => p.duration_unit === 'y' && p.min_duration === years);
    const price1Year = prices.find(p => p.duration_unit === 'y' && p.min_duration === 1);

    if (!yearPrice && !price1Year) {
      console.error('❌ Error: Pricing information not available');
      process.exit(1);
    }

    const registrationPrice = yearPrice || price1Year;
    const pricePerYear = registrationPrice.price_after_taxes;
    const currency = registrationPrice.currency;
    const totalCost = years * pricePerYear;

    console.log('💰 Pricing:');
    console.log(`   ${years} year(s): ${totalCost.toFixed(2)} ${currency}`);
    if (years > 1) {
      console.log(`   (${pricePerYear.toFixed(2)} ${currency} per year)`);
    }
    console.log('');

    if (domainInfo.discount) {
      console.log(`   💡 Discount applied: ${domainInfo.discount.message}`);
      console.log('');
    }

    // If dry-run, stop here
    if (dryRun) {
      console.log('🏁 Dry run complete. No registration performed.');
      console.log('');
      console.log('💡 To register this domain, run without --dry-run and provide contact info:');
      console.log(`   node register-domain.js ${domain} --years ${years} --contact owner.json`);
      return;
    }

    // Load and validate contact information
    let contact;

    if (contactFile) {
      // Load from specified file
      try {
        const contactData = fs.readFileSync(contactFile, 'utf8');
        contact = JSON.parse(contactData);
      } catch (err) {
        console.error(`❌ Error reading contact file: ${err.message}`);
        process.exit(1);
      }
    } else {
      // Try to load saved contact
      contact = loadSavedContact();

      if (!contact) {
        console.error('❌ Error: No contact information found');
        console.error('');
        console.error('Option 1: Setup default contact (recommended)');
        console.error('   node setup-contact.js');
        console.error('');
        console.error('Option 2: Provide contact file for this registration');
        console.error(`   node register-domain.js ${domain} --contact owner.json`);
        console.error('');
        console.error('Contact JSON format:');
        console.error('   {"given":"John","family":"Doe","email":"john@example.com",...}');
        process.exit(1);
      }

      console.log('📋 Using saved contact information');
      console.log('');
    }

    // Validate contact
    const validation = validateContact(contact);
    if (!validation.valid) {
      console.error('❌ Invalid contact information:');
      validation.errors.forEach(err => console.error(`   - ${err}`));
      console.error('');
      console.error('Required fields:');
      console.error('  given, family, email, streetaddr, city, zip, country, phone, type');
      process.exit(1);
    }

    console.log('📋 Contact Information:');
    console.log(`   Name: ${contact.given} ${contact.family}`);
    console.log(`   Email: ${contact.email}`);
    console.log(`   Address: ${contact.streetaddr}, ${contact.city}, ${contact.zip}`);
    console.log(`   Country: ${contact.country}`);
    console.log(`   Phone: ${contact.phone}`);
    console.log(`   Type: ${contact.type}`);
    if (contact.orgname) {
      console.log(`   Organization: ${contact.orgname}`);
    }
    console.log('');

    // Show registration summary
    console.log('═══════════════════════════════════════════════════════');
    console.log('                 REGISTRATION SUMMARY');
    console.log('═══════════════════════════════════════════════════════');
    console.log(`   Domain: ${domain}`);
    console.log(`   Duration: ${years} year(s)`);
    console.log(`   Auto-renewal: ${autoRenew ? 'ENABLED' : 'DISABLED'}`);
    console.log(`   TOTAL COST: ${totalCost.toFixed(2)} ${currency}`);
    console.log('═══════════════════════════════════════════════════════');
    console.log('');
    console.log('⚠️  WARNING: DOMAIN REGISTRATION IS NON-REFUNDABLE!');
    console.log('⚠️  You will be charged immediately.');
    console.log('⚠️  This action cannot be undone.');
    console.log('');

    // Require explicit "yes" confirmation
    const confirmed = await confirm('Type "yes" to confirm registration: ');

    if (!confirmed) {
      console.log('❌ Registration cancelled.');
      process.exit(0);
    }

    console.log('');
    console.log('⏳ Registering domain...');
    console.log('');

    // Register the domain
    const result = await registerDomain(domain, years, contact);

    console.log('✅ Domain registration initiated successfully!');
    console.log('');

    if (result.id) {
      console.log(`   Operation ID: ${result.id}`);
    }

    if (result.message) {
      console.log(`   Message: ${result.message}`);
    }

    console.log('');
    console.log('📧 You should receive a confirmation email shortly.');
    console.log('');

    // Set auto-renewal if requested
    if (autoRenew) {
      console.log('⚙️  Enabling auto-renewal...');
      try {
        await setAutoRenewal(domain, true, 1);
        console.log('✅ Auto-renewal enabled');
      } catch (err) {
        console.warn('⚠️  Could not enable auto-renewal:', err.message);
        console.warn('   You can enable it later using configure-autorenew.js');
      }
      console.log('');
    }

    // Purge contact if requested or preferred
    const shouldPurge = purgeContact || (contact._purgeAfterUse === true);
    if (shouldPurge && !contactFile) {
      // Only purge if using saved contact (not custom contact file)
      try {
        if (fs.existsSync(CONTACT_FILE)) {
          fs.unlinkSync(CONTACT_FILE);
          console.log('🗑️  Contact information deleted (privacy preference)');
          console.log('');
        }
      } catch (err) {
        console.warn('⚠️  Could not delete contact file:', err.message);
        console.log('');
      }
    }

    console.log('🎉 Registration complete!');
    console.log('');
    console.log('📝 Next steps:');
    console.log('   1. Wait for confirmation email');
    console.log('   2. Configure DNS records if needed');
    console.log(`   3. Check domain status: node list-domains.js`);

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('');
      console.error('Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('');
      console.error('Permission denied. Ensure your API token has Domain: write scope.');
      console.error('Create a new token at: https://admin.gandi.net/organizations/account/pat');
    } else if (error.statusCode === 402) {
      console.error('');
      console.error('Payment failed. Check your Gandi account balance or payment method.');
    } else if (error.statusCode === 409) {
      console.error('');
      console.error('Domain is no longer available. It may have been registered by someone else.');
    } else if (error.statusCode === 422) {
      console.error('');
      console.error('Validation failed. Check contact information and TLD requirements.');
      if (error.response) {
        console.error('Details:', JSON.stringify(error.response, null, 2));
      }
    } else if (error.response) {
      console.error('API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Renew an existing domain via Gandi Domain API
 * 
 * ⚠️  WARNING: Domain renewal costs real money and is NON-REFUNDABLE!
 * 
 * Usage:
 *   node renew-domain.js <domain> [options]
 * 
 * Options:
 *   --years <n>      Renewal duration (1-10 years, default: 1)
 *   --dry-run        Check pricing without renewing
 * 
 * Examples:
 *   node renew-domain.js example.com --dry-run
 *   node renew-domain.js example.com --years 2
 */

import {
  getDomain,
  checkAvailability,
  renewDomain
} from './gandi-api.js';
import readline from 'readline';

// Parse command line arguments
const args = process.argv.slice(2);

if (args.length < 1) {
  console.error('Usage: node renew-domain.js <domain> [options]');
  console.error('');
  console.error('Options:');
  console.error('  --years <n>      Renewal duration (1-10 years, default: 1)');
  console.error('  --dry-run        Check pricing without renewing');
  console.error('');
  console.error('⚠️  WARNING: Domain renewal costs real money and is NON-REFUNDABLE!');
  console.error('');
  console.error('Examples:');
  console.error('  node renew-domain.js example.com --dry-run');
  console.error('  node renew-domain.js example.com --years 2');
  process.exit(1);
}

const domain = args[0];
let years = 1;
let dryRun = false;

// Parse options
for (let i = 1; i < args.length; i++) {
  if (args[i] === '--years' && args[i + 1]) {
    years = parseInt(args[i + 1], 10);
    i++;
  } else if (args[i] === '--dry-run') {
    dryRun = true;
  }
}

// Validate years
if (isNaN(years) || years < 1 || years > 10) {
  console.error('❌ Error: Years must be between 1 and 10');
  process.exit(1);
}

// Prompt for confirmation
function confirm(message) {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    rl.question(message, (answer) => {
      rl.close();
      resolve(answer.toLowerCase() === 'yes');
    });
  });
}

// Format date nicely
function formatDate(dateString) {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', { 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });
}

// Main function
async function main() {
  try {
    console.log('🔍 Checking domain information...');
    console.log('');

    // Get current domain info
    let domainInfo;
    try {
      domainInfo = await getDomain(domain);
    } catch (err) {
      if (err.statusCode === 404) {
        console.error(`❌ Domain ${domain} not found in your account`);
        console.error('   Make sure you own this domain and it\'s registered with Gandi.');
      } else {
        throw err;
      }
      process.exit(1);
    }

    // Show current domain status
    console.log(`📋 Domain: ${domain}`);
    console.log(`   Current expiration: ${formatDate(domainInfo.dates.registry_ends_at)}`);

    const daysUntilExpiry = Math.ceil((new Date(domainInfo.dates.registry_ends_at) - new Date()) / (1000 * 60 * 60 * 24));
    console.log(`   Days until expiry: ${daysUntilExpiry}`);

    if (domainInfo.autorenew) {
      console.log(`   Auto-renewal: ✅ ENABLED (${domainInfo.autorenew.duration} year(s))`);
    } else {
      console.log('   Auto-renewal: ❌ DISABLED');
    }

    console.log('');

    // Check if domain is renewable
    if (daysUntilExpiry > 365) {
      console.log('⚠️  Note: Domain expires in more than 1 year.');
      console.log('   Renewal will extend the expiration date from the current expiry,');
      console.log('   not from today\'s date.');
      console.log('');
    }

    // Get renewal pricing
    console.log('💰 Checking renewal pricing...');
    const availability = await checkAvailability([domain]);
    const pricingInfo = availability.products?.[0];

    if (!pricingInfo || !pricingInfo.prices) {
      console.error('❌ Error: Could not retrieve pricing information');
      process.exit(1);
    }

    const prices = pricingInfo.prices;
    const yearPrice = prices.find(p => p.duration_unit === 'y' && p.min_duration === years);
    const price1Year = prices.find(p => p.duration_unit === 'y' && p.min_duration === 1);

    if (!yearPrice && !price1Year) {
      console.error('❌ Error: Pricing information not available');
      process.exit(1);
    }

    const renewalPrice = yearPrice || price1Year;
    const pricePerYear = renewalPrice.price_after_taxes;
    const currency = renewalPrice.currency;
    const totalCost = years * pricePerYear;

    console.log('');
    console.log('💰 Renewal Pricing:');
    console.log(`   ${years} year(s): ${totalCost.toFixed(2)} ${currency}`);
    if (years > 1) {
      console.log(`   (${pricePerYear.toFixed(2)} ${currency} per year)`);
    }
    console.log('');

    // Calculate new expiration date
    const currentExpiry = new Date(domainInfo.dates.registry_ends_at);
    const newExpiry = new Date(currentExpiry);
    newExpiry.setFullYear(newExpiry.getFullYear() + years);

    console.log('📅 After renewal:');
    console.log(`   New expiration: ${formatDate(newExpiry)}`);
    console.log('');

    // If dry-run, stop here
    if (dryRun) {
      console.log('🏁 Dry run complete. No renewal performed.');
      console.log('');
      console.log('💡 To renew this domain, run without --dry-run:');
      console.log(`   node renew-domain.js ${domain} --years ${years}`);
      return;
    }

    // Show renewal summary
    console.log('═══════════════════════════════════════════════════════');
    console.log('                   RENEWAL SUMMARY');
    console.log('═══════════════════════════════════════════════════════');
    console.log(`   Domain: ${domain}`);
    console.log(`   Current expiry: ${formatDate(currentExpiry)}`);
    console.log(`   Renewal duration: ${years} year(s)`);
    console.log(`   New expiry: ${formatDate(newExpiry)}`);
    console.log(`   TOTAL COST: ${totalCost.toFixed(2)} ${currency}`);
    console.log('═══════════════════════════════════════════════════════');
    console.log('');
    console.log('⚠️  WARNING: DOMAIN RENEWAL IS NON-REFUNDABLE!');
    console.log('⚠️  You will be charged immediately.');
    console.log('⚠️  This action cannot be undone.');
    console.log('');

    // Require explicit "yes" confirmation
    const confirmed = await confirm('Type "yes" to confirm renewal: ');

    if (!confirmed) {
      console.log('❌ Renewal cancelled.');
      process.exit(0);
    }

    console.log('');
    console.log('⏳ Renewing domain...');
    console.log('');

    // Renew the domain
    const result = await renewDomain(domain, years);

    console.log('✅ Domain renewal successful!');
    console.log('');

    if (result.id) {
      console.log(`   Operation ID: ${result.id}`);
    }

    if (result.message) {
      console.log(`   Message: ${result.message}`);
    }

    console.log('');
    console.log('📧 You should receive a confirmation email shortly.');
    console.log('');
    console.log('🎉 Renewal complete!');
    console.log('');
    console.log(`   ${domain} is now renewed until ${formatDate(newExpiry)}`);
    console.log('');
    console.log('💡 Consider enabling auto-renewal to prevent accidental expiration:');
    console.log(`   node configure-autorenew.js ${domain} --enable`);

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('');
      console.error('Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('');
      console.error('Permission denied. Ensure your API token has Domain: write scope.');
      console.error('Create a new token at: https://admin.gandi.net/organizations/account/pat');
    } else if (error.statusCode === 402) {
      console.error('');
      console.error('Payment failed. Check your Gandi account balance or payment method.');
    } else if (error.statusCode === 404) {
      console.error('');
      console.error('Domain not found or not accessible.');
    } else if (error.statusCode === 422) {
      console.error('');
      console.error('Renewal not allowed at this time. Domain may be:');
      console.error('  - Already renewed to maximum duration');
      console.error('  - In grace or redemption period');
      console.error('  - Locked or suspended');
      if (error.response) {
        console.error('Details:', JSON.stringify(error.response, null, 2));
      }
    } else if (error.response) {
      console.error('API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Request SSL/TLS certificate via Gandi
 * 
 * ⚠️  WARNING: Gandi SSL certificates may have costs. Check pricing before requesting.
 * 
 * Usage:
 *   node request-certificate.js <domain> [options]
 * 
 * Options:
 *   --method <dns|email|http>   Validation method (default: dns)
 *   --dry-run                   Show what would be requested without requesting
 * 
 * Examples:
 *   node request-certificate.js example.com --dry-run
 *   node request-certificate.js example.com --method dns
 */

import {
  getDomain,
  requestCertificate
} from './gandi-api.js';
import readline from 'readline';

// Parse command line arguments
const args = process.argv.slice(2);

if (args.length < 1) {
  console.error('Usage: node request-certificate.js <domain> [options]');
  console.error('');
  console.error('Options:');
  console.error('  --method <dns|email|http>   Validation method (default: dns)');
  console.error('  --dry-run                   Check setup without requesting');
  console.error('');
  console.error('⚠️  WARNING: Gandi SSL certificates may have costs associated with them.');
  console.error('');
  console.error('Examples:');
  console.error('  node request-certificate.js example.com --dry-run');
  console.error('  node request-certificate.js example.com --method dns');
  console.error('');
  console.error('💡 Note: This requests certificates through Gandi\'s certificate service.');
  console.error('   For free Let\'s Encrypt certificates, consider using certbot or acme.sh');
  console.error('   directly on your web server.');
  process.exit(1);
}

const domain = args[0];
let method = 'dns';
let dryRun = false;

// Parse options
for (let i = 1; i < args.length; i++) {
  if (args[i] === '--method' && args[i + 1]) {
    method = args[i + 1].toLowerCase();
    i++;
  } else if (args[i] === '--dry-run') {
    dryRun = true;
  }
}

// Validate method
if (!['dns', 'email', 'http'].includes(method)) {
  console.error(`❌ Invalid validation method: ${method}`);
  console.error('   Valid methods: dns, email, http');
  process.exit(1);
}

// Prompt for confirmation
function confirm(message) {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    rl.question(message, (answer) => {
      rl.close();
      resolve(answer.toLowerCase() === 'yes');
    });
  });
}

// Main function
async function main() {
  try {
    console.log(`🔒 SSL Certificate Request for ${domain}`);
    console.log('');

    // Check if domain exists
    let domainInfo;
    try {
      domainInfo = await getDomain(domain);
    } catch (err) {
      if (err.statusCode === 404) {
        console.error(`❌ Domain ${domain} not found in your account`);
        process.exit(1);
      }
      throw err;
    }

    console.log('📋 Domain verified in your account');
    console.log('');

    // Show validation method info
    console.log('🔐 Validation Method:');
    console.log('');

    if (method === 'dns') {
      console.log('   Method: DNS Validation (dns-01)');
      console.log('   • You will need to add TXT records to your DNS');
      console.log('   • Records will be provided after request');
      console.log('   • Validation happens automatically once records are added');
      console.log('   • Works with wildcard certificates');
    } else if (method === 'email') {
      console.log('   Method: Email Validation');
      console.log('   • Validation email sent to domain admin addresses');
      console.log('   • Valid addresses: admin@, webmaster@, postmaster@');
      console.log('   • Click link in email to validate');
      console.log('   • Does not work for wildcard certificates');
    } else if (method === 'http') {
      console.log('   Method: HTTP Validation (http-01)');
      console.log('   • File placed on your web server for validation');
      console.log('   • Must be accessible via HTTP on port 80');
      console.log('   • Does not work for wildcard certificates');
    }

    console.log('');

    // Dry run check
    if (dryRun) {
      console.log('🏁 Dry run complete. No certificate requested.');
      console.log('');
      console.log('💡 To request this certificate, run without --dry-run');
      console.log('');
      console.log('⚠️  IMPORTANT: Gandi SSL certificates may have associated costs.');
      console.log('   Check your Gandi account pricing before proceeding.');
      console.log('   https://www.gandi.net/en-US/domain/ssl');
      return;
    }

    // Warning and confirmation
    console.log('═'.repeat(70));
