#!/usr/bin/env node

/**
 * Restore DNS zone from a snapshot
 * Usage: node restore-snapshot.js <domain> <snapshot-id> [--force]
 */

import { restoreSnapshot, listSnapshots } from './gandi-api.js';
import readline from 'readline';

const args = process.argv.slice(2);
const force = args.includes('--force');
const [domain, snapshotId] = args.filter(arg => !arg.startsWith('--'));

if (!domain || !snapshotId) {
  console.error('❌ Usage: node restore-snapshot.js <domain> <snapshot-id> [--force]');
  console.error('');
  console.error('Examples:');
  console.error('  node restore-snapshot.js example.com abc123-def456-ghi789');
  console.error('  node restore-snapshot.js example.com abc123-def456-ghi789 --force');
  console.error('');
  console.error('Options:');
  console.error('  --force    Skip confirmation prompt');
  console.error('');
  console.error('💡 To list available snapshots:');
  console.error('   node list-snapshots.js ' + (domain || '<domain>'));
  process.exit(1);
}

async function confirmRestore(snapshot) {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    console.log('');
    console.log('⚠️  WARNING: This will REPLACE all current DNS records!');
    console.log(`   Restoring snapshot: "${snapshot.name}"`);
    console.log(`   Created: ${new Date(snapshot.created_at).toLocaleString()}`);
    if (snapshot.zone_data) {
      console.log(`   Will restore ${snapshot.zone_data.length} record(s)`);
    }
    console.log('');

    rl.question('Are you sure you want to restore? Type "restore" to confirm: ', (answer) => {
      rl.close();
      resolve(answer.toLowerCase() === 'restore');
    });
  });
}

async function main() {
  try {
    console.log(`🔍 Finding snapshot for ${domain}...`);
    console.log('');

    // Get snapshot details
    const snapshots = await listSnapshots(domain);
    const snapshot = snapshots.find(s => (s.uuid || s.id) === snapshotId);

    if (!snapshot) {
      console.error(`❌ Snapshot not found: ${snapshotId}`);
      console.error('');
      console.error('💡 List available snapshots with:');
      console.error(`   node list-snapshots.js ${domain}`);
      process.exit(1);
    }

    console.log('📋 Snapshot details:');
    console.log(`   ID: ${snapshot.uuid || snapshot.id}`);
    console.log(`   Name: ${snapshot.name}`);
    console.log(`   Created: ${new Date(snapshot.created_at).toLocaleString()}`);
    if (snapshot.zone_data) {
      console.log(`   Records: ${snapshot.zone_data.length}`);
    }

    // Confirm restoration (unless --force)
    if (!force) {
      const confirmed = await confirmRestore(snapshot);
      if (!confirmed) {
        console.log('');
        console.log('❌ Restoration cancelled.');
        process.exit(0);
      }
    }

    // Restore the snapshot
    console.log('');
    console.log('🔄 Restoring DNS zone from snapshot...');
    await restoreSnapshot(domain, snapshotId);

    console.log('✅ DNS zone restored successfully!');
    console.log('');
    console.log('⏱️  DNS propagation may take a few minutes.');
    console.log('   Verify with: node list-dns.js ' + domain);

  } catch (error) {
    console.error('❌ Error:', error.message);

    if (error.statusCode === 401) {
      console.error('   Authentication failed. Check your API token.');
    } else if (error.statusCode === 403) {
      console.error('   Permission denied. Ensure your token has LiveDNS write access.');
    } else if (error.statusCode === 404) {
      console.error(`   Domain ${domain} or snapshot not found.`);
    } else if (error.response) {
      console.error('   API response:', JSON.stringify(error.response, null, 2));
    }

    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Setup default contact information for domain registration
 * 
 * Saves contact info to ~/.config/gandi/contact.json for reuse in:
 * - Domain registration
 * - Domain renewal
 * - Domain transfers
 * 
 * Usage:
 *   node setup-contact.js
 */

import fs from 'fs';
import path from 'path';
import os from 'os';
import readline from 'readline';

const CONFIG_DIR = path.join(os.homedir(), '.config', 'gandi');
const CONTACT_FILE = path.join(CONFIG_DIR, 'contact.json');

// US state codes (ISO 3166-2 format)
const US_STATES = {
  'AL': 'US-AL', 'AK': 'US-AK', 'AZ': 'US-AZ', 'AR': 'US-AR', 'CA': 'US-CA',
  'CO': 'US-CO', 'CT': 'US-CT', 'DE': 'US-DE', 'FL': 'US-FL', 'GA': 'US-GA',
  'HI': 'US-HI', 'ID': 'US-ID', 'IL': 'US-IL', 'IN': 'US-IN', 'IA': 'US-IA',
  'KS': 'US-KS', 'KY': 'US-KY', 'LA': 'US-LA', 'ME': 'US-ME', 'MD': 'US-MD',
  'MA': 'US-MA', 'MI': 'US-MI', 'MN': 'US-MN', 'MS': 'US-MS', 'MO': 'US-MO',
  'MT': 'US-MT', 'NE': 'US-NE', 'NV': 'US-NV', 'NH': 'US-NH', 'NJ': 'US-NJ',
  'NM': 'US-NM', 'NY': 'US-NY', 'NC': 'US-NC', 'ND': 'US-ND', 'OH': 'US-OH',
  'OK': 'US-OK', 'OR': 'US-OR', 'PA': 'US-PA', 'RI': 'US-RI', 'SC': 'US-SC',
  'SD': 'US-SD', 'TN': 'US-TN', 'TX': 'US-TX', 'UT': 'US-UT', 'VT': 'US-VT',
  'VA': 'US-VA', 'WA': 'US-WA', 'WV': 'US-WV', 'WI': 'US-WI', 'WY': 'US-WY',
  'DC': 'US-DC'
};

function prompt(question, defaultValue = '') {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    const displayQuestion = defaultValue 
      ? `${question} [${defaultValue}]: `
      : `${question}: `;

    rl.question(displayQuestion, (answer) => {
      rl.close();
      resolve(answer.trim() || defaultValue);
    });
  });
}

function validateEmail(email) {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
}

function validatePhone(phone) {
  // International format: +1.5551234567
  const regex = /^\+\d{1,3}\.\d{6,15}$/;
  return regex.test(phone);
}

function formatPhone(phone) {
  // Convert common formats to Gandi format
  // +1-513-410-1823 → +1.5134101823
  // (513) 410-1823 → +1.5134101823 (assumes US)

  // Remove all non-digit characters except leading +
  let cleaned = phone.replace(/[^\d+]/g, '');

  // If no country code, assume +1 (US)
  if (!cleaned.startsWith('+')) {
    cleaned = '+1' + cleaned;
  }

  // Split into country code and number
  const match = cleaned.match(/^(\+\d{1,3})(\d+)$/);
  if (match) {
    return `${match[1]}.${match[2]}`;
  }

  return phone; // Return original if can't parse
}

function formatState(state, country) {
  if (country === 'US') {
    const upperState = state.toUpperCase();
    // Check if already in ISO format
    if (upperState.startsWith('US-')) {
      return upperState;
    }
    // Convert abbreviation to ISO format
    if (US_STATES[upperState]) {
      return US_STATES[upperState];
    }
  }
  return state;
}

async function main() {
  console.log('🔧 Gandi Contact Setup\n');
  console.log('This will save your contact information for domain registration.');
  console.log('All information is stored locally at: ' + CONTACT_FILE);
  console.log('');

  // Check if contact file exists
  let existingContact = null;
  if (fs.existsSync(CONTACT_FILE)) {
    console.log('⚠️  Contact file already exists!\n');
    const overwrite = await prompt('Overwrite existing contact? (yes/no)', 'no');
    if (overwrite.toLowerCase() !== 'yes') {
      console.log('❌ Setup cancelled.');
      process.exit(0);
    }
    console.log('');

    // Load existing for defaults
    try {
      existingContact = JSON.parse(fs.readFileSync(CONTACT_FILE, 'utf8'));
    } catch (err) {
      // Ignore parse errors
    }
  }

  const contact = {};

  // Type
  console.log('📋 Contact Type');
  const typeInput = await prompt('Type (individual/company)', existingContact?.type || 'individual');
  contact.type = typeInput.toLowerCase();
  console.log('');

  // Name
  console.log('👤 Name');
  contact.given = await prompt('First name', existingContact?.given);
  contact.family = await prompt('Last name', existingContact?.family);
  console.log('');

  // Email
  console.log('📧 Email');
  let email;
  while (true) {
    email = await prompt('Email address', existingContact?.email);
    if (validateEmail(email)) {
      contact.email = email;
      break;
    }
    console.log('❌ Invalid email format. Please try again.');
  }
  console.log('');

  // Phone
  console.log('📞 Phone');
  console.log('   Format: +1.5551234567 (international with country code)');
  let phone;
  while (true) {
    const phoneInput = await prompt('Phone number', existingContact?.phone);
    phone = formatPhone(phoneInput);
    if (validatePhone(phone)) {
      contact.phone = phone;
      console.log(`   ✓ Formatted as: ${phone}`);
      break;
    }
    console.log('❌ Invalid phone format. Use international format: +1.5551234567');
  }
  console.log('');

  // Address
  console.log('🏠 Address');
  contact.streetaddr = await prompt('Street address', existingContact?.streetaddr);
  contact.city = await prompt('City', existingContact?.city);

  // Country
  const country = await prompt('Country (2-letter code, e.g., US)', existingContact?.country || 'US');
  contact.country = country.toUpperCase();

  // State (if applicable)
  if (contact.country === 'US') {
    console.log('   Format: 2-letter abbreviation (e.g., OH for Ohio)');
    const stateInput = await prompt('State', existingContact?.state?.replace('US-', ''));
    contact.state = formatState(stateInput, contact.country);
    console.log(`   ✓ Formatted as: ${contact.state}`);
  } else {
    const state = await prompt('State/Province (optional)', existingContact?.state || '');
    if (state) {
      contact.state = state;
    }
  }

  contact.zip = await prompt('ZIP/Postal code', existingContact?.zip);
  console.log('');

  // Summary
  console.log('═══════════════════════════════════════════════════════');
  console.log('📋 CONTACT SUMMARY');
  console.log('═══════════════════════════════════════════════════════');
  console.log(`   Name: ${contact.given} ${contact.family}`);
  console.log(`   Email: ${contact.email}`);
  console.log(`   Phone: ${contact.phone}`);
  console.log(`   Address: ${contact.streetaddr}`);
  console.log(`            ${contact.city}, ${contact.state || ''} ${contact.zip}`);
  console.log(`            ${contact.country}`);
  console.log(`   Type: ${contact.type}`);
  console.log('═══════════════════════════════════════════════════════');
  console.log('');

  const confirm = await prompt('Save this contact? (yes/no)', 'yes');
  if (confirm.toLowerCase() !== 'yes') {
    console.log('❌ Setup cancelled.');
    process.exit(0);
  }

  console.log('');
  console.log('🔒 Privacy Preference');
  console.log('');
  console.log('How should contact information be handled after domain registration?');
  console.log('');
  console.log('   RETAIN (recommended): Keep contact saved for future registrations');
  console.log('   PURGE: Delete contact automatically after each registration');
  console.log('');
  const purgeChoice = await prompt('Auto-purge after registration? (yes/no)', 'no');
  contact._purgeAfterUse = (purgeChoice.toLowerCase() === 'yes');

  console.log('');
  if (contact._purgeAfterUse) {
    console.log('   ✓ Contact will be deleted after each successful registration');
  } else {
    console.log('   ✓ Contact will be retained for reuse (delete manually with delete-contact.js)');
  }

  // Ensure config directory exists
  if (!fs.existsSync(CONFIG_DIR)) {
    fs.mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 });
  }

  // Save contact
  fs.writeFileSync(CONTACT_FILE, JSON.stringify(contact, null, 2), { mode: 0o600 });

  console.log('');
  console.log('✅ Contact saved successfully!');
  console.log('');
  console.log(`   Location: ${CONTACT_FILE}`);
  console.log(`   Permissions: 600 (owner read-write only)`);
  console.log('');
  console.log('💡 This contact will be used automatically for:');
  console.log('   • Domain registration (register-domain.js)');
  console.log('   • Domain renewal (renew-domain.js)');
  console.log('   • Domain transfers');
  console.log('');
  console.log('📝 To view or edit your contact:');
  console.log('   node view-contact.js');
  console.log('   node setup-contact.js  (re-run setup)');
  console.log('');
  console.log('🎉 Setup complete!');
}

main().catch(err => {
  console.error('❌ Error:', err.message);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * Domain Suggestion Tool
 * Smart disambiguation with TLD variations and name alternatives
 * 
 * Usage:
 *   node suggest-domains.js example
 *   node suggest-domains.js example.com  (will extract base name)
 *   node suggest-domains.js example --tlds com,net,org
 *   node suggest-domains.js example --no-variations
 */

import { checkAvailability, generateVariations, readDomainCheckerConfig, getRateLimiter } from './gandi-api.js';

// Parse arguments
const args = process.argv.slice(2);
if (args.length === 0 || args[0] === '--help' || args[0] === '-h') {
  console.log('Usage: node suggest-domains.js <domain> [options]');
  console.log('');
  console.log('Options:');
  console.log('  --tlds <list>        Comma-separated TLD list (e.g., com,net,org)');
  console.log('  --no-variations      Skip name variations, only check TLDs');
  console.log('  --variations-only    Skip exact TLD matches, only show variations');
  console.log('  --json               Output as JSON');
  console.log('');
  console.log('Limits (configurable in config/domain-checker-defaults.json):');
  console.log('  • Max TLDs: 5 (default)');
  console.log('  • Max variations: 10 (default)');
  console.log('  • Rate limit: 3 concurrent, 200ms delay, 100 req/min max');
  console.log('');
  console.log('Examples:');
  console.log('  node suggest-domains.js example');
  console.log('  node suggest-domains.js example.com --tlds com,net,io');
  console.log('  node suggest-domains.js example --no-variations');
  process.exit(0);
}

const input = args[0];
const flags = {
  tlds: args.includes('--tlds') ? args[args.indexOf('--tlds') + 1].split(',') : null,
  noVariations: args.includes('--no-variations'),
  variationsOnly: args.includes('--variations-only'),
  json: args.includes('--json')
};

// Extract base name (remove TLD if present)
const baseName = input.includes('.') ? input.split('.')[0] : input;

// Load config
const config = readDomainCheckerConfig();
const rateLimiter = getRateLimiter(config.rateLimit);

// Determine TLD list
let tlds = [];
if (flags.tlds) {
  tlds = flags.tlds;
} else {
  const tldConfig = config.tlds;
  if (tldConfig.mode === 'replace' && tldConfig.custom.length > 0) {
    tlds = tldConfig.custom;
  } else {
    tlds = [...tldConfig.defaults, ...tldConfig.custom];
  }
}

// Apply TLD limit
const maxTlds = config.limits?.maxTlds || 5;
if (tlds.length > maxTlds && !flags.tlds) {
  if (!flags.json) {
    console.log(`ℹ️  Limiting to ${maxTlds} TLDs (configurable in config)`);
  }
  tlds = tlds.slice(0, maxTlds);
}

if (!flags.json) {
  console.log(`🔍 Checking availability for: ${baseName}\n`);
  console.log(`📊 Checking ${tlds.length} TLDs${flags.noVariations ? '' : ' and generating variations'}...\n`);
}

try {
  const results = {
    exact: [],
    variations: {}
  };

  // Check exact matches (different TLDs)
  if (!flags.variationsOnly) {
    const exactDomains = tlds.map(tld => `${baseName}.${tld}`);

    if (!flags.json) {
      console.log(`Checking ${exactDomains.length} exact TLD matches...`);
    }

    // Check each domain individually with rate limiting
    // (batch checking has issues - see #5)
    for (const domain of exactDomains) {
      try {
        const result = await rateLimiter.throttle(async () => {
          return await checkAvailability([domain]);
        });

        if (result && result.products && result.products.length > 0) {
          const product = result.products[0];
          const currency = result.currency || 'USD';
          results.exact.push({
            domain: product.name,
            available: product.status === 'available',
            status: product.status,
            price: product.prices ? `${product.prices[0].price_after_taxes.toFixed(2)} ${currency}` : null,
            tld: product.tld
          });
        }
      } catch (error) {
        // Continue on error for individual domains
        if (!flags.json) {
          console.error(`  ⚠️  Error checking ${domain}: ${error.message}`);
        }
      }
    }
  }

  // Generate and check variations
  if (!flags.noVariations && config.variations?.enabled) {
    const variations = generateVariations(baseName, config.variations);

    // Flatten all variations and cap to maxVariations
    const maxVariations = config.limits?.maxVariations || 10;
    let allVariationNames = [];
    for (const [pattern, names] of Object.entries(variations)) {
      allVariationNames.push(...names.map(name => ({ pattern, name })));
    }

    if (allVariationNames.length > maxVariations) {
      if (!flags.json) {
        console.log(`ℹ️  Limiting to ${maxVariations} variations (configurable in config)`);
      }
      allVariationNames = allVariationNames.slice(0, maxVariations);
    }

    if (!flags.json && allVariationNames.length > 0) {
      console.log(`Checking ${allVariationNames.length} name variations...`);
    }

    // Check variations
    const primaryTlds = flags.tlds ? flags.tlds.slice(0, 2) : config.tlds.defaults.slice(0, 2); // Just com, net

    for (const { pattern, name } of allVariationNames) {
      if (!results.variations[pattern]) {
        results.variations[pattern] = [];
      }

      // Check each TLD for this variation
      for (const tld of primaryTlds) {
        const domain = `${name}.${tld}`;

        try {
          const result = await rateLimiter.throttle(async () => {
            return await checkAvailability([domain]);
          });

          if (result && result.products && result.products.length > 0) {
            const product = result.products[0];
            const currency = result.currency || 'USD';

            if (product.status === 'available') {
              results.variations[pattern].push({
                domain: product.name,
                available: true,
                status: product.status,
                price: product.prices ? `${product.prices[0].price_after_taxes.toFixed(2)} ${currency}` : null,
                tld: product.tld
              });
            }
          }
        } catch (error) {
          // Continue on error
          if (!flags.json) {
            console.error(`  ⚠️  Error checking ${domain}: ${error.message}`);
          }
        }
      }
    }
  }

  // Output results
  if (flags.json) {
    console.log(JSON.stringify(results, null, 2));
  } else {
    displayResults(results, flags);
  }

} catch (error) {
  console.error('❌ Error:', error.message);
  if (error.response) {
    console.error('API Response:', error.response);
  }
  process.exit(1);
}

/**
 * Display results in human-readable format
 */
function displayResults(results, flags) {
  // Show exact matches
  if (!flags.variationsOnly && results.exact.length > 0) {
    console.log('═══════════════════════════════════════════════════════');
    console.log('📋 EXACT MATCHES (Different TLDs)');
    console.log('═══════════════════════════════════════════════════════\n');

    const available = results.exact.filter(r => r.available);
    const unavailable = results.exact.filter(r => !r.available);

    if (available.length > 0) {
      console.log('✅ Available:\n');
      available.forEach(r => {
        console.log(`  ${r.domain.padEnd(30)} ${r.price || 'N/A'}`);
      });
      console.log('');
    }

    if (unavailable.length > 0) {
      console.log('❌ Unavailable:\n');
      unavailable.forEach(r => {
        console.log(`  ${r.domain.padEnd(30)} (${r.status})`);
      });
      console.log('');
    }
  }

  // Show variations
  if (!flags.noVariations && Object.keys(results.variations).length > 0) {
    console.log('═══════════════════════════════════════════════════════');
    console.log('🎨 NAME VARIATIONS');
    console.log('═══════════════════════════════════════════════════════\n');

    for (const [pattern, domains] of Object.entries(results.variations)) {
      if (domains.length === 0) continue;

      const patternLabel = pattern.charAt(0).toUpperCase() + pattern.slice(1);
      console.log(`${patternLabel}:\n`);

      domains.forEach(r => {
        console.log(`  ✅ ${r.domain.padEnd(30)} ${r.price || 'N/A'}`);
      });
      console.log('');
    }
  }

  // Summary
  const totalAvailable = results.exact.filter(r => r.available).length +
                         Object.values(results.variations).flat().length;

  console.log('═══════════════════════════════════════════════════════');
  console.log(`📊 SUMMARY: ${totalAvailable} available domains found`);
  console.log('═══════════════════════════════════════════════════════');
}

